import type { Node_Type } from './../../../ricos-types/index.js';
import { findParentNodeClosestToPos } from './../../../tiptap/helpers/index.js';

import type { QueryItem } from '../../types.js';

const NAME = 'isChildOfNode';
const isChildOfNodeFn: QueryItem =
  ({ editorQuery }) =>
  (nodeTypeName: Node_Type) => {
    const selection = editorQuery.editor.view.state.selection;
    const { $from } = selection;
    const parentNode = findParentNodeClosestToPos($from, node => node.type.name === nodeTypeName);

    return !!parentNode;
  };

export const isChildOfNode = { NAME, query: isChildOfNodeFn };
