import React from 'react';

import type { EditorPlugins } from './editor-plugins.js';

type PluginGlobalComponentsProps = {
  plugins: EditorPlugins;
};

export const PluginGlobalComponents: React.FC<PluginGlobalComponentsProps> = ({ plugins }) => {
  const components = plugins.getPluginGlobalComponents();

  if (components.length === 0) {
    return <></>;
  }

  return components.map((Component, index) => <Component key={index} />);
};
