import React, { useContext } from 'react';

import { RicosContext } from './../../ricos-context/index.js';
import type { ModalProps } from './../../ricos-types/index.js';
import { FocusManager } from './../../_shared/focus-manager/focus-manager.js';
import { UiComponentsProvider } from './../../ui-components/index.js';

import styles from '../statics/styles/fullscreen-scss.js';

export const Fullscreen = ({ children, zIndex }: ModalProps) => {
  const { jsdomMode } = useContext(RicosContext);
  const [ref, setRef] = React.useState<HTMLDivElement | null>(null);
  return (
    <FocusManager
      focusTrapOptions={{
        returnFocusOnDeactivate: false,
      }}
      jsdomMode={jsdomMode}
    >
      <div
        className={styles.fullscreen}
        style={{ zIndex }}
        ref={setRef}
        //  oxlint-disable-next-line jsx-a11y/no-noninteractive-tabindex
        tabIndex={0}
        aria-modal
        role="dialog"
      >
        {ref && <UiComponentsProvider containerEl={ref}>{children}</UiComponentsProvider>}
      </div>
    </FocusManager>
  );
};
