import type { Subscription, TopicDescriptor } from './../ricos-types/index.js';

import type { RicosEventData } from './event-data.js';
import type { Event, Subscriber } from './models/event.js';
import type { Topic } from './models/topics.js';
import type {
  AsyncPublishingMetadata,
  EventLogger,
  SyncPublishingMetadata,
} from './ricos-event-logger.js';
import { RicosTopic } from './topics.js';

export class EventInitializationError extends Error {}

class DisposedEventAccessError extends Error {}

export class RicosEvent implements Event<RicosEventData> {
  private readonly topic: RicosTopic;

  private static eventId = 0;

  private subscribers: EventSubscriber[] = [];

  private isActive = true;

  private logger: EventLogger;

  constructor(topicDescriptor: TopicDescriptor, logger: EventLogger) {
    this.logger = logger;
    const topic = RicosTopic.fromString(topicDescriptor);
    if (topic.isWildcard()) {
      throw new EventInitializationError(
        `cannot create event with wildcard topic ${topicDescriptor}`
      );
    }
    this.topic = topic;
  }

  subscribe(
    handler: (topic: TopicDescriptor, data: RicosEventData) => void,
    subscriberId: string
  ): Subscription {
    const subscriber = new EventSubscriber(handler, subscriberId);
    if (this.isDuplicateSubscriber(subscriber)) {
      // It seems it makes sense to have multiple subscribers, but here we are
      // wondering why this warn was here in the first place.
      // console.warn(
      //   `A duplicate subscriber ${subscriberId} for topic ${this.topic} detected.`,
      //   `Possible reasons: multiple instances of the same component subscribing, or wrong lifecycle management.`
      // );
    }
    // @ts-ignore $TSFixMe
    this.subscribers.push(subscriber);
    this.logger.log(`[${this.topic}]: ${subscriberId} subscribed`);
    return {
      topic: this.topic.toString(),
      cancel: () => {
        this.logger.log(`[${this.topic}]: ${subscriberId} unsubscribed`);
        this.subscribers = this.subscribers.filter((s: EventSubscriber) => s !== subscriber);
      },
    };
  }

  private isDuplicateSubscriber(subscriber: EventSubscriber) {
    return this.subscribers.some(s => s.id === subscriber.id);
  }

  publishSync(data: RicosEventData): boolean {
    if (!this.isActive) {
      throw new DisposedEventAccessError(`[${this.topic}] cannot publish disposed event`);
    }
    const t1 = performance.now();
    const processings = this.subscribers.map(subscriber => {
      const t3 = performance.now();
      subscriber.invoke(this.topic.toString(), data);
      const t4 = performance.now();
      return {
        subscriberId: subscriber.id,
        duration: t4 - t3,
      };
    });
    const t2 = performance.now();
    const metadata: SyncPublishingMetadata = {
      topic: this.topic.toString(),
      eventId: ++RicosEvent.eventId,
      data,
      duration: t2 - t1,
      timestamp: new Date(),
      isAsync: false,
      processings,
    };
    this.logger.log(metadata);
    return this.subscribers.length > 0;
  }

  publish(data: RicosEventData): boolean {
    if (!this.isActive) {
      throw new DisposedEventAccessError(`[${this.topic}] cannot publish disposed event`);
    }
    const t1 = performance.now();
    this.subscribers.forEach(subscriber =>
      setTimeout(() => subscriber.invoke(this.topic.toString(), data), 0)
    );
    const t2 = performance.now();
    const metadata: AsyncPublishingMetadata = {
      topic: this.topic.toString(),
      eventId: ++RicosEvent.eventId,
      data,
      duration: t2 - t1,
      timestamp: new Date(),
      isAsync: true,
    };
    this.logger.log(metadata);
    return this.subscribers.length > 0;
  }

  publishOnce(data: RicosEventData): boolean {
    const published = this.publish(data);
    if (published) {
      this.dispose();
    }
    return published;
  }

  getTopic(): Topic {
    return this.topic;
  }

  dispose() {
    this.subscribers = [];
    this.isActive = false;
    this.logger.log(`[${this.topic}]: event disposed`);
  }
}

export class EventSubscriber implements Subscriber<RicosEventData> {
  readonly callback: (topic: TopicDescriptor, data: RicosEventData) => void;

  readonly id: string;

  constructor(callback: (topic: TopicDescriptor, data: RicosEventData) => void, id: string) {
    this.id = id;
    this.callback = callback;
  }

  invoke(topic: TopicDescriptor, data: RicosEventData): void {
    this.callback(topic, data);
  }
}
