import { isPresent } from 'ts-is-present';

import type {
  AddButton,
  EditorPlugin as EditorPluginType,
  IRicosEditor,
  PluginExports,
  PublicCommands,
  QuickAction,
  RicosServices,
  TextButton,
} from './../ricos-types/index.js';
import { deepMerge } from './../_shared/deep-merge.js';
import type { Selection } from './../tiptap/pm/state.js';

import { EditorPlugin } from './editor-plugin.js';
import { mergeConfig } from './merge-config.js';

export type PluginServices = Omit<
  RicosServices,
  'plugins' | 'editor' | 'zIndexService' | 'getEditorQuery'
>;

export class PluginCollisionError extends Error {}

export class EditorPlugins {
  private plugins: EditorPlugin[] = [];

  private services: PluginServices & { plugins?: EditorPlugins };

  private publicCommands?: PublicCommands;

  static mergeConfig = mergeConfig;

  constructor(services: PluginServices) {
    this.services = services;
  }

  register(plugin: EditorPluginType) {
    const { isMobile } = this.services?.context || {};
    if (isMobile && plugin?.disableOnMobile) {
      return;
    }
    const candidate = EditorPlugin.of(plugin, { ...this.services, plugins: this });
    const duplicate = this.hasDuplicate(candidate);
    if (duplicate) {
      throw new PluginCollisionError(
        `the plugin ${candidate.getType()} conflicts with ${duplicate.getType()}`
      );
    }

    candidate.register();
    this.plugins.push(candidate);
  }

  unregister(plugin: EditorPlugin) {
    plugin.unregister();
    return this.filter(p => !p.equals(plugin));
  }

  destroy() {
    this.plugins.map(p => p.unregister());
    this.plugins = [];
  }

  filter(predicate: (plugin: EditorPlugin) => boolean) {
    this.plugins = this.plugins.filter(predicate);
    return this.plugins;
  }

  asArray() {
    return this.plugins;
  }

  getConfig(type: string) {
    return this.plugins.filter(plugin => plugin.getType() === type)[0]?.getConfig() || {};
  }

  getTextButtons(): TextButton[] {
    return this.plugins.flatMap(plugin => plugin.getTextButtons() || []);
  }

  getQuickActions(): QuickAction[] {
    return this.plugins.flatMap(plugin => plugin.getQuickActions());
  }

  getAddButtons(): AddButton[] {
    //maybe use filter class func
    return this.plugins.flatMap(plugin => plugin.getAddButtons() || []);
  }

  getFloatingToolbarButtons() {
    return this.plugins
      .flatMap(plugin => plugin.getFloatingToolbarButton())
      .filter(isPresent)
      .sort(({ priority: a }, { priority: b }) => b - a);
  }

  getExports() {
    return this.plugins
      .map(plugin => plugin.getExports())
      .filter(isPresent)
      .reduce(
        (integrations, pluginIntegrations) => {
          return deepMerge(integrations, pluginIntegrations);
        },
        {} as Partial<PluginExports>
      );
  }

  getVisibleToolbar(selection: Selection, editor: IRicosEditor) {
    const toolbar = this.plugins
      .flatMap(plugin => plugin.getToolbars())
      .find(toolbar => !!toolbar?.isVisible(selection, editor));
    return toolbar;
  }

  getTiptapExtensions() {
    return this.plugins.flatMap(plugin => plugin.getTiptapExtensions?.() || []).filter(x => !!x);
  }

  getPluginProviders() {
    return this.plugins.map(plugin => plugin.getProvider()).filter(isPresent);
  }

  getPluginGlobalComponents() {
    return this.plugins.map(plugin => plugin.getGlobalComponent()).filter(isPresent);
  }

  isFooterToolbarDisabled(selection: $TSFixMe) {
    const nodeType = selection?.node.type.name;
    if (nodeType) {
      const selectedPlugin = this.plugins.find(
        plugin => plugin?.getTiptapExtensions()?.[0]?.name === nodeType
      );
      return !!selectedPlugin?.getTiptapExtensions()?.[0]?.groups.includes('footer-disabled');
    }
    return false;
  }

  private hasDuplicate(plugin: EditorPlugin) {
    return this.plugins.find(p => p.equals(plugin));
  }

  setPublicCommands(publicCommands: PublicCommands) {
    this.publicCommands = publicCommands;
  }

  getPublicCommands() {
    return this.publicCommands;
  }
}
