import type { Context } from 'react';
import React, { useContext, useEffect, useState } from 'react';

import type { SelectorContextValue } from './../_shared/use-context-selector.js';
import { createContext, useContextSelector } from './../_shared/use-context-selector.js';
import type { Selection } from './../tiptap/pm/state.js';

import { EditorContext } from './editor-context.js';

export type SelectionContextType = {
  selection: Selection | null;
};

const SelectionContext = createContext({} as SelectionContextType);

export const SelectionContextProvider = ({
  children,
  onSelectorContextValue,
}: {
  children: React.ReactNode;
  onSelectorContextValue: (
    selectorContextValue: SelectorContextValue<SelectionContextType>
  ) => void;
}) => {
  const {
    adapter: { tiptapEditor },
  } = useContext(EditorContext);

  const [selection, setSelection] = useState<Selection | null>(null);

  useEffect(() => {
    const updateSelection = () => {
      setSelection(tiptapEditor.state.selection);
    };

    tiptapEditor.on('selectionUpdate', updateSelection);

    return () => {
      tiptapEditor.off('selectionUpdate', updateSelection);
    };
  }, []);

  return (
    <SelectionContext.Provider value={React.useMemo(() => ({ selection }), [selection])}>
      <SelectorContextValuePasser onSelectorContextValue={onSelectorContextValue} />
      {children}
    </SelectionContext.Provider>
  );
};

export const useSelection = () => {
  return useContextSelector(SelectionContext, id => id, Object.is);
};

const SelectorContextValuePasser = ({
  onSelectorContextValue,
}: {
  onSelectorContextValue: (
    selectorContextValue: SelectorContextValue<SelectionContextType>
  ) => void;
}) => {
  const contextValue = useContext(
    SelectionContext as unknown as Context<SelectorContextValue<SelectionContextType>>
  );
  onSelectorContextValue(contextValue);
  return null;
};
