import type { ToolbarSettingsFunctions } from './../../ricos-types/index.js';

export const getButtonsListFromConfig = (
  toolbarConfig: ToolbarSettingsFunctions,
  buttonsType: 'desktop' | 'mobile'
) => {
  if (!('getButtons' in toolbarConfig) || toolbarConfig.getButtons === undefined) {
    return [];
  }
  const buttonsPerType = toolbarConfig.getButtons();

  if (buttonsType === 'desktop') {
    return buttonsPerType.desktop ?? [];
  }
  return (isIOS() ? buttonsPerType.mobile?.ios : buttonsPerType.mobile?.android) ?? [];
};

const isIOS = () => {
  return (
    typeof navigator !== 'undefined' &&
    (['iPad Simulator', 'iPhone Simulator', 'iPod Simulator', 'iPad', 'iPhone', 'iPod'].includes(
      navigator.platform
    ) ||
      // iPad on iOS 13 detection
      (navigator.userAgent.includes('Mac') && 'ontouchend' in document))
  );
};
