import type { FC, ReactNode } from 'react';
import React, { useEffect, useMemo } from 'react';

import { useConverters } from './../pm-converters/context.js';
import type { Editor } from './../tiptap/react/index.js';

import { ContentQueryContext } from './content-query-context.js';
import { RicosContentQueryService } from './content-query-service.js';

export type ContentQueryProviderProps = {
  editor: Editor;
  children: ReactNode;
};

export const ContentQueryProvider: FC<ContentQueryProviderProps> = (
  props: ContentQueryProviderProps
) => {
  const { children, editor } = props;
  const converters = useConverters();

  const contentQueryService = useMemo(() => {
    const service = new RicosContentQueryService();
    service.setEditor(editor, converters);
    return service;
  }, []);

  useEffect(() => {
    contentQueryService.setEditor(editor, converters);
  }, [editor, converters, contentQueryService]);

  return (
    <ContentQueryContext.Provider value={contentQueryService}>
      {children}
    </ContentQueryContext.Provider>
  );
};
