/**
 * Check if object1 includes object2
 * @param object1 Object
 * @param object2 Object
 */

export function objectIncludes(
  object1: Record<string, any>,

  object2: Record<string, any>,
  options: { strict: boolean } = { strict: true }
): boolean {
  const keys = Object.keys(object2);

  if (!keys.length) {
    return true;
  }

  return keys.every(key => {
    if (options.strict) {
      return object2[key] === object1[key];
    }

    // Realm-safe RegExp check (matches lodash.isRegExp): `instanceof` is false
    // for regex objects created in another realm (iframe/window).
    if (Object.prototype.toString.call(object2[key]) === '[object RegExp]') {
      return (object2[key] as RegExp).test(object1[key]);
    }

    return object2[key] === object1[key];
  });
}
