import type { PmConverters } from './../../pm-converters/collect.js';
import type { Decoration } from './../../ricos-schema/next-schema/index.js';
import type { Editor } from './../../tiptap/core/index.js';

export class EditorStateQuery {
  // oxlint-disable-next-line no-useless-constructor
  constructor(
    private editor: Editor,
    private converters: PmConverters
  ) {}

  storedDecorations(): Decoration[] | null {
    if (this.editor.state.storedMarks === null) {
      return null;
    }
    return this.converters.marksToDecorations(this.editor.state.storedMarks.map(m => m.toJSON()));
  }
}
