import type { Decoration } from './../../../ricos-schema/next-schema/index.js';
import type { Decoration_Type } from './../../../ricos-types/index.js';

import type { IEditorQuery, QueryItem } from '../../types.js';
import { objectIncludes } from '../utils.js';

const NAME = 'activeDecorationsByType';

const activeDecorationsByType: QueryItem =
  ({ editorQuery }: { editorQuery: IEditorQuery }) =>
  (decorationType: Decoration_Type, attrs?: Record<string, unknown>) => {
    const selectedNodesDecorations = editorQuery
      .selection()
      .doc.descendants(node => node.isText())
      .map(node => {
        return editorQuery.styles().getComputedDecoration(node, decorationType);
      });

    let allDecorations = [...selectedNodesDecorations];

    // referece: tiptap IsMarkedActive
    if (editorQuery.selection().isEmpty) {
      const storedDecorations = editorQuery.state().storedDecorations();
      if (storedDecorations) {
        allDecorations = [...allDecorations, ...storedDecorations];
      } else {
        allDecorations = [...allDecorations, ...editorQuery.selection().collapsedDecorations];
      }
    }

    const activeDecorations = allDecorations
      .filter(decoration => !!decoration)
      .filter(decoration => decoration?.type === decorationType)
      .filter(decoration => {
        return objectIncludes(decoration as Decoration, attrs || {}, { strict: false });
      });

    return activeDecorations;
  };

export const activeDecorationByType = { NAME, query: activeDecorationsByType };
