import * as E from 'fp-ts-esm/Either';
import { identity, pipe } from 'fp-ts-esm/function';

import { getMatches } from './../ricos-content/index.js';
import type {
  BasicKeyCombination,
  ModifierKeys,
  NavigationKeys,
  Platform,
  TriggerKey,
  WhitespaceKeys,
} from './../ricos-types/index.js';
import { isModifierKey, isTriggerKey } from './../ricos-types/index.js';

class KeyboardShortcutParseError extends Error {}

/**
 * Represents shortcut key combination
 *
 */
export class Keys {
  modifiers: ModifierKeys[];

  key: TriggerKey;

  private readonly macOsMap: Record<ModifierKeys & WhitespaceKeys & NavigationKeys, string> = {
    Meta: '⌘',
    Ctrl: '⌃',
    Alt: '⌥',
    Shift: '⇧',
    Enter: '↩',
    Space: '␣',
    Backspace: '⌫',
    Tab: '⇥',
    Escape: '⎋',
    Arrow: '← ↑ ↓ →',
    ArrowLeft: '←',
    ArrowRight: '→',
    ArrowUp: '↑',
    ArrowDown: '↓',
    Delete: '⌦',
    Home: '⇱',
    End: '⇲',
    PageUp: '⇞',
    PageDown: '⇟',
    Insert: '⌤',
    AltGraph: '⌥',
  };

  private readonly windowsMap: Record<ModifierKeys & WhitespaceKeys & NavigationKeys, string> = {
    Meta: '⊞',
    Ctrl: 'Ctrl',
    Alt: 'Alt',
    Shift: '⇧',
    Enter: '⏎',
    Space: '␣',
    Backspace: '⟵',
    Tab: '↹',
    Escape: 'Esc',
    Arrow: '← ↑ ↓ →',
    ArrowLeft: '←',
    ArrowRight: '→',
    ArrowUp: '↑',
    ArrowDown: '↓',
    Delete: 'Del',
    Home: 'Home',
    End: 'End',
    PageUp: 'PgUp',
    PageDown: 'PgDn',
    Insert: 'Ins',
    AltGraph: 'AltGr',
  };

  private static isValidKeys(key: string, modifiers: string[]): key is TriggerKey {
    return isTriggerKey(key) && modifiers.filter(Boolean).every(isModifierKey);
  }

  private constructor(key: string, modifiers: string[] = []) {
    if (!Keys.isValidKeys(key, modifiers)) {
      throw new KeyboardShortcutParseError(
        `invalid keys combination: modifiers = ${modifiers.join('+')} | key = ${key}`
      );
    }
    this.modifiers = modifiers.filter(Boolean) as ModifierKeys[];
    this.key = key;
  }

  /**
   * Textual representation of parsed Keys:
   * ```ts
   *  `${modifiers}+${keys}`
   * ```
   * @memberof Keys
   */
  toString(): string {
    return `${
      this.modifiers.length > 0 ? this.modifiers.sort().filter(Boolean).join('+').concat('+') : ''
    }${this.key}`;
  }

  toPlatformString(platform: Platform): string {
    return platform === 'macOs' ? this.toMacOsString() : this.toWindowsString();
  }

  private toMacOsString(): string {
    return (
      this.modifiers
        // @ts-expect-error $TSFixMe
        .map(modifier => this.macOsMap[modifier])
        // @ts-expect-error $TSFixMe
        .concat(this.macOsMap[this.key] || this.key)
        .join(' ')
    );
  }

  private toWindowsString(): string {
    return (
      this.modifiers
        // @ts-expect-error $TSFixMe
        .map(modifier => this.windowsMap[modifier])
        // @ts-expect-error $TSFixMe
        .concat(this.windowsMap[this.key] || this.key)
        .join(' ')
    );
  }

  toTooltipHint(platform: Platform): string {
    // NOTE: replaceAll is not a function on Node.js v14
    return this.toPlatformString(platform).replace(/ /g, platform === 'macOs' ? '' : '+');
  }

  equals(keys: Keys): boolean {
    return this.toString() === keys.toString();
  }

  /**
   * Parses keys string
   *
   * Example: 'Control+B' parsed to
   * ```ts
   *  {
   *    modifiers: ['Control'],
   *    key: ['B']
   *  }
   * ```
   *
   * @param {BasicKeyCombination} keys key combination
   * @returns  {Keys} Keys instance
   * @memberof Keys
   */
  static parse(keys: BasicKeyCombination): Keys {
    return pipe(
      keys,
      getMatches(/(?:([^+]+)\+)?(?:([^+]+)\+)?(.+)/gi),
      E.fromOption(() => new KeyboardShortcutParseError(`invalid keys combination: ${keys}`)),
      E.map(
        ([, modifier1, modifier2, key]: string[]) =>
          new Keys(key, [modifier1, modifier2].filter(Boolean) as ModifierKeys[])
      ),
      E.fold(e => {
        throw e;
      }, identity)
    );
  }
}
