import type { ReferenceType } from '@floating-ui/react-dom';
import { autoUpdate, flip, offset, shift, useFloating } from '@floating-ui/react-dom';
import React, { useContext, useEffect, useState } from 'react';

import { RicosContext, ZIndexContext } from './../../ricos-context/index.js';
import { useDraggableModal } from './../hooks/use-draggable-modal.js';
import type { ModalProps, Placement } from './../../ricos-types/index.js';
import { FocusManager } from './../../_shared/focus-manager/focus-manager.js';
import { ClickOutside, UiComponentsProvider } from './../../ui-components/index.js';

export const Floating = ({ children, modalConfig, closeModal }: ModalProps) => {
  const { jsdomMode, environment } = useContext(RicosContext);
  const zIndexService = useContext(ZIndexContext);
  const [modalElement, setModalElement] = useState<HTMLDivElement | null>(null);
  const [clampedY, setClampedY] = useState<number | null>(null);
  const { autoFocus = true, initialFocus, positioning } = modalConfig || {};
  let placement = positioning?.placement;
  const referenceElement = positioning?.referenceElement as HTMLElement;

  if (environment === 'wixel' && (placement === 'right-start' || placement === 'bottom')) {
    placement = 'bottom-start';
  }

  const middlewares =
    placement === 'right' || placement === 'right-start--custom-offset'
      ? [offset({ mainAxis: 8 })]
      : placement === 'right-start'
        ? [offset({ mainAxis: 32, crossAxis: -78 })]
        : placement === 'bottom' || placement === 'bottom-start' || placement === 'bottom-end'
          ? [offset({ mainAxis: 8 }), flip()]
          : placement === 'left' || placement === 'left-start' || placement === 'left-end'
            ? [offset({ mainAxis: 8 }), flip()]
            : placement === 'right-end'
              ? [offset({ mainAxis: 20 }), flip()]
              : [];

  const {
    x,
    y,
    isPositioned,
    refs: { setReference, setFloating },
    strategy,
  } = useFloating({
    placement: toFloatingPlacement(placement),
    strategy: 'fixed',
    middleware: [
      ...middlewares,
      shift({
        crossAxis: true,
      }),
    ],
    ...(modalConfig?.sticky && {
      whileElementsMounted: (referenceEl, floatingEl, update) => {
        return autoUpdate(referenceEl, floatingEl, update, {
          animationFrame: true,
        });
      },
    }),
  });

  useEffect(() => {
    setReference(referenceElement as ReferenceType);
  }, [setReference, referenceElement]);

  const coords = useDraggableModal({
    modalElement,
    dragHandleSelector: modalConfig.enableDrag
      ? modalConfig.dragHandleSelector
      : '[data-drag-handle]',
  });

  useEffect(() => {
    setClampedY(null);
  }, [coords]);

  useEffect(() => {
    if (!modalElement) {
      return;
    }

    let prevHeight = modalElement.getBoundingClientRect().height;

    const observer = new ResizeObserver(() => {
      const currentHeight = modalElement.getBoundingClientRect().height;
      const grew = currentHeight > prevHeight;
      prevHeight = currentHeight;

      if (!grew) {
        return;
      }

      const rect = modalElement.getBoundingClientRect();
      const overflow = rect.bottom - window.innerHeight;

      if (overflow > 0) {
        setClampedY(Math.max(0, rect.top - overflow));
      }
    });

    observer.observe(modalElement);
    return () => observer.disconnect();
  }, [modalElement]);

  const isVisible = jsdomMode || isPositioned;
  const content = (
    <div
      ref={ref => {
        setFloating(ref);
        setModalElement(ref);
      }}
      style={{
        top: clampedY ?? coords?.y ?? y ?? '',
        left: coords?.x ?? x ?? '',
        position: strategy,
        zIndex: zIndexService.getZIndex('DIALOG'),
        display: 'block',
        visibility: isVisible ? 'visible' : 'hidden',
      }}
    >
      {modalElement && (
        <UiComponentsProvider containerEl={modalElement}>{children}</UiComponentsProvider>
      )}
    </div>
  );

  const onClickOutside = (event: PointerEvent) => {
    const clickOutsideHandler =
      typeof modalConfig.onClickOutside === 'function'
        ? modalConfig.onClickOutside
        : modalConfig.onClickOutside?.handler;

    // A modal's own tooltips are appended to the ricos portal, so they are outside
    // this element even though they belong to it — clicking one used to close the
    // modal out from under the user. `table-spacing-modal.tsx` makes the same
    // exception in its own click-outside handler.
    if ((event.target as HTMLElement | null)?.closest('[role="tooltip"]')) {
      return;
    }

    if (clickOutsideHandler) {
      clickOutsideHandler(event);
    } else if (
      referenceElement instanceof HTMLElement &&
      !referenceElement?.contains(event.target as Node)
    ) {
      closeModal();
    }
  };

  return (
    <ClickOutside
      onClickOutside={onClickOutside}
      triggerOn={
        typeof modalConfig.onClickOutside !== 'function'
          ? modalConfig.onClickOutside?.on
          : undefined
      }
    >
      {autoFocus ? (
        <FocusManager
          focusTrapOptions={{
            returnFocusOnDeactivate: false,
            fallbackFocus: document.activeElement as HTMLElement,
            ...(initialFocus !== undefined && { initialFocus }),
          }}
          jsdomMode={jsdomMode}
          active={isVisible}
          preventScroll
        >
          {content}
        </FocusManager>
      ) : (
        content
      )}
    </ClickOutside>
  );
};

const toFloatingPlacement = (placement?: Placement) => {
  if (placement === 'right-start--custom-offset') {
    return 'right-start';
  }
  if (placement === 'overlay') {
    return 'bottom-start';
  }
  return placement;
};
