import type { AiMessage, AiMessageInsert, AiMessageReplace } from './types.js';

const getPrevActionableMessageIndex = (aiMessages: AiMessage[], startIndex: number) => {
  for (let i = startIndex - 1; i >= 0; i--) {
    if (aiMessages[i].type !== 'text') {
      return i;
    }
  }
  // If no previous actionable message found, wrap around to the last one
  for (let i = aiMessages.length - 1; i > startIndex; i--) {
    if (aiMessages[i].type !== 'text') {
      return i;
    }
  }
  return startIndex; // No other actionable messages found
};

const getNextActionableMessageIndex = (aiMessages: AiMessage[], startIndex: number) => {
  for (let i = startIndex + 1; i < aiMessages.length; i++) {
    if (aiMessages[i].type !== 'text') {
      return i;
    }
  }
  // If no next actionable message found, wrap around to the first one
  for (let i = 0; i < startIndex; i++) {
    if (aiMessages[i].type !== 'text') {
      return i;
    }
  }
  return startIndex; // No other actionable messages found
};

export type PagerAPI = {
  current: number; // 1-based index of the current actionable message
  currentUndone: boolean;
  toggleUndo: () => void;
  total: number; // total number of actionable messages
  onPrev: () => void; // function to navigate to the previous actionable message
  onNext: () => void; // function to navigate to the next actionable message
};

export const getPagerAPI = (
  aiMessages: AiMessage[],
  activeMessageIndex: number,
  setActiveMessageIndex: (index: number) => void,
  setAiMessages: (arg: React.SetStateAction<AiMessage[]>) => void
): PagerAPI => {
  const actionableMessages = aiMessages.filter(m => m.type !== 'text' && m.type !== 'theme');
  const total = actionableMessages.length;
  const current = actionableMessages.findIndex(m => m === aiMessages[activeMessageIndex]);
  if (!total || current === -1) {
    return {
      current: 0,
      total: 0,
      currentUndone: false,
      toggleUndo: () => {},
      onPrev: () => {},
      onNext: () => {},
    };
  }

  const onPrev = () => {
    const prevIndex = getPrevActionableMessageIndex(aiMessages, activeMessageIndex);
    setActiveMessageIndex(prevIndex);
    const prevMessage = aiMessages[prevIndex] as AiMessageReplace | AiMessageInsert;

    prevMessage.aiRegion?.overlay?.scrollIntoView({
      behavior: 'instant',
      block: 'center',
    });
  };

  const onNext = () => {
    const nextIndex = getNextActionableMessageIndex(aiMessages, activeMessageIndex);
    setActiveMessageIndex(nextIndex);
    const nextMessage = aiMessages[nextIndex] as AiMessageReplace | AiMessageInsert;

    nextMessage.aiRegion?.overlay?.scrollIntoView({
      behavior: 'instant',
      block: 'center',
    });
  };

  const currentMessage = aiMessages[activeMessageIndex] as AiMessageReplace | AiMessageInsert;

  return {
    current,
    total,
    onPrev,
    onNext,
    currentUndone: currentMessage.viewBefore,
    toggleUndo: () => {
      setAiMessages(prevMessages =>
        prevMessages.map((msg, index) => {
          if (index === activeMessageIndex && (msg.type === 'replace' || msg.type === 'insert')) {
            return {
              ...msg,
              viewBefore: !msg.viewBefore,
            };
          }
          return msg;
        })
      );
    },
  };
};
