import { useRef } from 'react';

import { useMockInlineAiResponseChunks } from './../ricos-context/dev-context.js';
import type { RicosDocumentNode } from './../ricos-schema/next-schema/index.js';
import { validateRicosDocument } from './../ricos-schema/next-schema/index.js';
import { logInvariant } from './../_shared/log-invariant.js';
import { useRequestService } from './../_shared/request-service-provider/request-service-provider.js';
import { useWixInstanceService } from './../_shared/request-service-provider/wix-instance-context.js';
import { unreachable } from './../_shared/uncreachable.js';
import { useContextSelector } from './../_shared/use-context-selector.js';

import { patchTheme } from '../theme-utils/patch-theme.js';
import { parseChunk } from './convert-to-ai-messages.js';
import { doPromptStreamOfStreams } from './do-prompt-stream-of-streams.js';
import { filterOutExternalNodes } from './filter-out-external-nodes.js';
import { InlineAiContext } from './inline-ai-context.js';
import { mergeNonRootAiMessages } from './merge-non-root-ai-messages.js';
import type {
  AiMessage,
  AiMessageText,
  DoPromptStreamArgs,
  InlineAiRunningState,
  InlineAiService,
  InlineAiState,
  MetadataChunk,
} from './types.js';

/**
 * Whether `s` still represents the run identified by `executionId`.
 *
 * False for every state that is not an in-flight run — which is the point: a
 * cancelled session sits in 'typing' and a superseded one carries the newer run's
 * id, so both answer false and the abandoned run stops writing. Without this, a
 * still-polling first run would append its chunks to a second run's messages,
 * since both write to the same invocation slice.
 *
 * This is the guard that stops an abandoned run from *writing*. A separate
 * `latestExecution` ref stops it from *polling* — see useExecutePrompt.
 */
export const isExecutionCurrent = (
  s: InlineAiState | undefined,
  executionId: string
): s is InlineAiRunningState =>
  s !== undefined &&
  (s.type === 'pending' || s.type === 'streaming') &&
  s.executionId === executionId;

export const useExecutePrompt = (
  aiProjectId?: string,
  useWixelWidgets?: boolean
): InlineAiService['executePrompt'] => {
  const mockInlineAiResponseChunks = useMockInlineAiResponseChunks();
  const { makeRequest } = useRequestService();
  const instance = useWixInstanceService();

  // The execution that currently owns each invocation's slice. Written synchronously when a
  // run starts, so an abandoned run's loop notices on its very next chunk instead of waiting
  // for a state updater to run. Declared before the guard below so the hook stays unconditional.
  const latestExecution = useRef<Record<string, string>>({});

  const inlineAiCtx = useContextSelector(
    InlineAiContext,
    ctx => ctx,
    () => true
  );
  if (!inlineAiCtx) {
    return () => {};
  }
  const [, setInlineAiState] = inlineAiCtx;

  return async ({
    prompt,
    selection,
    document: doc,
    getCurrentTheme,
    invocationId,
    files,
    onThemeChange,
    traceParams,
    systemPromptId,
  }) => {
    // One per execution attempt, not per session: the server allows each
    // idempotency key to run at most once, so a resubmit after cancel needs a
    // fresh one. It also identifies this run's writes against the shared slice.
    const executionId = crypto.randomUUID();
    latestExecution.current[invocationId] = executionId;

    const setState = (newState: React.SetStateAction<InlineAiState>) =>
      setInlineAiState(prevState => {
        const currentInvocationState = prevState.invocations[invocationId];
        const nextInvocationState =
          typeof newState === 'function' ? newState(currentInvocationState) : newState;
        return {
          ...prevState,
          invocations: {
            ...prevState.invocations,
            [invocationId]: nextInvocationState,
          },
        };
      });

    const whatsNext = await new Promise<'abort' | 'continue'>(resolve =>
      setState(s => {
        if (!s) {
          // external invocation
          resolve('continue');
          return { type: 'pending', prompt, executionId };
        }
        if (s.type === 'typing') {
          // we come from typing state
          resolve('continue');
          return { type: 'pending', prompt, executionId };
        }
        // race condition: another prompt execution for same invocationId is ongoing
        resolve('abort');
        return s;
      })
    );

    if (whatsNext === 'abort') {
      return;
    }

    const metadataChunks: MetadataChunk[] = [];
    const streamArgs: DoPromptStreamArgs = {
      prompt,
      document: doc,
      selection,
      makeRequest,
      getCurrentTheme,
      invocationId,
      executionId,
      files,
      metasiteId: instance().metaSiteId,
      traceParams,
      systemPromptId,
    };
    const stream = mockInlineAiResponseChunks
      ? mockInlineAiResponseChunks(streamArgs)
      : doPromptStreamOfStreams({
          ...streamArgs,
          aiProjectId,
          useWixelWidgets,
        });
    for await (const chunk of stream) {
      // Only stops this run from polling on forever once a newer one has taken the slice;
      // isExecutionCurrent below is what guarantees it never writes. Deliberately not the
      // same check: a cancel returns the session to 'typing' without starting a new run, so
      // it moves isExecutionCurrent but not this ref — the updater still bails out.
      if (latestExecution.current[invocationId] !== executionId) {
        return;
      }
      if ('chunk' in chunk && chunk.chunk.type === 'METADATA') {
        metadataChunks.push(chunk.chunk);
      } else {
        if ('chunk' in chunk && chunk.chunk.type === 'THEME') {
          const currentTheme = getCurrentTheme?.() || {};
          const aiPartialTheme = chunk.chunk.themeOptions.theme;
          const patchedTheme = patchTheme(currentTheme, aiPartialTheme);

          onThemeChange?.(patchedTheme);
        }
        setState(s => {
          if (!isExecutionCurrent(s, executionId)) {
            // Cancelled, or a newer run owns the slice now.
            return s;
          }
          if ('type' in chunk && chunk.type === 'error') {
            return {
              type: 'error',
              error: {
                message: chunk.message,
                status: chunk.status,
                applicationErrorCode: chunk.applicationErrorCode,
              },
              messages: 'messages' in s ? s.messages : [],
              chunks: 'chunks' in s ? s.chunks : [],
              prompt: 'prompt' in s ? s.prompt : '',
            };
          }
          if (s.type === 'pending') {
            return {
              type: 'streaming',
              chunks: [chunk],
              messages: parseChunk([], chunk, doc),
              prompt: s.prompt,
              executionId,
            };
          } else if (s.type === 'streaming') {
            return {
              type: 'streaming',
              chunks: [...s.chunks, chunk],
              messages: parseChunk(s.messages, chunk, doc),
              prompt: s.prompt,
              executionId,
            };
          } else {
            logInvariant(unreachable(s));
            return s;
          }
        });
      }
    }
    setState(s => {
      if (!isExecutionCurrent(s, executionId)) {
        // The run was cancelled or superseded while its stream was still open.
        // Reaching the end is then expected, not an invariant violation.
        return s;
      }
      if (s.type === 'pending') {
        // ai didn't send any chunks
        return {
          type: 'error' as const,
          error: { message: 'No response from AI service' },
          prompt: s.prompt,
          messages: [],
          chunks: [],
        };
      }

      const messages = s.messages.map(
        m =>
          ({
            ...m,
            completed: true,
            nodes:
              m.type !== 'text' && m.type !== 'theme'
                ? // Dirty fix for backend issue when it doesn't remove 'pending' flag on completion
                  filterOutExternalNodes(m.nodes ?? [])
                : [],
          }) as AiMessage
      );

      const errorMessages = messages.filter(
        (m): m is AiMessageText => m.type === 'text' && m.subtype === 'error'
      );
      if (errorMessages.length > 0) {
        return {
          type: 'error' as const,
          error: {
            message: errorMessages.map(m => m.text).join('\n'),
            applicationErrorCode: 'AI_GENERATED_ERROR',
          },
          prompt: s.prompt,
          messages,
          chunks: s.chunks,
        };
      }

      const mergedMessages = mergeNonRootAiMessages(doc, messages);

      let someMessageHadInvalidDocument = false;
      Promise.all(
        mergedMessages.map(async m => {
          if (m.type === 'text' || m.type === 'theme' || !m.isRootLevel) {
            return m;
          }
          const result = validateRicosDocument({ nodes: m.nodes });
          if (result.type === 'ok') {
            return m;
          }
          someMessageHadInvalidDocument = true;
          console.warn('\x1b[31m RICOS INVALID DOCUMENT CREATED \x1b[0m');
          const fixedNodes = await fixRicosDocument(makeRequest, m.nodes);
          return { ...m, nodes: fixedNodes };
        })
      )
        .then(fixedMessages => {
          // Streaming completion goes directly to 'closed' (auto-accept)
          setState({
            type: 'closed' as const,
            chunks: s.chunks,
            // we leave original un-merged messages if we didn't have to fix anything
            messages: someMessageHadInvalidDocument ? fixedMessages : messages,
            prompt: s.prompt,
          });
        })
        .catch(err => {
          setState({
            type: 'error' as const,
            error: { message: 'Failed to fix AI generated content: ' + err.message },
            prompt: s.prompt,
            messages,
            chunks: s.chunks,
          });
        });
      // while we fix, keep the streaming state
      return s;
    });
  };
};

const fixRicosDocument = (
  makeRequest: any,
  nodes: RicosDocumentNode[]
): Promise<RicosDocumentNode[]> => {
  const baseUrl =
    typeof location !== 'undefined' && location.hostname === 'editor.wix.com'
      ? 'https://editor.wix.com/_api/ricos-document-api/v1/ricos-document'
      : 'https://www.wixapis.com/ricos/v1/ricos-document';
  return makeRequest(`${baseUrl}/validate`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({
      document: { nodes },
      fixDocument: true,
      // TODO: use sdk package
      plugins: [
        'CARD',
        'VIDEO',
        'VERTICAL_EMBED',
        'TEXT_HIGHLIGHT',
        'TEXT_COLOR',
        'TABLE',
        'SPOILER',
        'POLL',
        'MENTIONS',
        'LINK_PREVIEW',
        'LINK_BUTTON',
        'LINK',
        'LINE_SPACING',
        'LAYOUT',
        'INDENT',
        'IMAGE',
        'HTML',
        'HEADING',
        'HASHTAG',
        'GIPHY',
        'GALLERY',
        'FILE',
        'EMOJI',
        'DIVIDER',
        'COLLAPSIBLE_LIST',
        'CODE_BLOCK',
        'AUDIO',
        'ACTION_BUTTON',
      ],
    }),
  })
    .then((res: any) => res.json())
    .then((res: any) => res.validDocument.nodes);
};
