import React, { useContext, useEffect } from 'react';

import {
  desktopTextButtonList,
  mobileTextButtonList,
} from './../ricos-plugins/toolbar-utils/default-text-formatting-buttons.js';
import { mergeToolbarSettings } from './../ricos-plugins/toolbar-utils/merge-toolbar-settings.js';
import type {
  TextButtons,
  ToolbarSettings,
  ToolbarSettingsFunctions,
  ToolbarType,
} from './../ricos-types/index.js';
import { getSelectedNodes } from './../_shared/get-selected-nodes.js';
import type { SelectorContextValue } from './../_shared/use-context-selector.js';
import { createContext, useContextSelector } from './../_shared/use-context-selector.js';
import type { Node } from './../tiptap/pm/model.js';
import type { Transaction } from './../tiptap/pm/state.js';
import { getDefaultToolbarSettings } from './../toolbars-v3/default-toolbar-settings.js';
import { supportedInsertButtonNames } from './../toolbars-v3/to-schema-base-id.js';

import { EditorContext } from './editor-context.js';
import { PluginsContext } from './plugins-context.js';
import { RicosContext } from './ricos-context.js';

export type ToolbarContextType = {
  toolbarSettings: ToolbarSettings | undefined;
  toolbarSettingsFunction: ToolbarSettingsFunctions[];
};

export type ToolbarState = {
  resolvedToolbarSettings: ToolbarSettingsFunctions[];
} & Omit<ToolbarSettings, 'getToolbarSettings'>;

const ToolbarStateContext = createContext<ToolbarState>({} as ToolbarState);
const textButtons: TextButtons = {
  mobile: mobileTextButtonList,
  desktop: desktopTextButtonList,
};

export const ToolbarContextProvider = ({
  toolbarSettings = {},
  onSelectorContextValue,
  children,
}: {
  toolbarSettings: ToolbarSettings | undefined;
  onSelectorContextValue: (selectorContextValue: SelectorContextValue<ToolbarState>) => void;
  children: React.ReactNode;
}) => {
  const {
    adapter: { tiptapEditor },
  } = useContext(EditorContext);
  const { content } = useContext(RicosContext);
  const [selectedNodes, setSelectedNodes] = React.useState<Node[]>([]);

  useEffect(() => {
    const updateContent = () => {
      const newSelectedNodes = getSelectedNodes(tiptapEditor);
      setSelectedNodes(newSelectedNodes);
      content.update(newSelectedNodes, tiptapEditor);
    };

    const onTransaction = ({ transaction }: { transaction: Transaction }) => {
      if (transaction.storedMarksSet || transaction.getMeta('forceToolbarUpdate')) {
        updateContent();
      }
    };

    tiptapEditor.on('transaction', onTransaction);
    tiptapEditor.on('update', updateContent);
    tiptapEditor.on('focus', updateContent);
    tiptapEditor.on('selectionUpdate', updateContent);

    return () => {
      tiptapEditor.off('transaction', onTransaction);
      tiptapEditor.off('update', updateContent);
      tiptapEditor.off('focus', updateContent);
      tiptapEditor.off('selectionUpdate', updateContent);
    };
  }, []);

  const resolvedToolbarSettings = useResolveToolbarSettings(toolbarSettings);

  const { getToolbarSettings, ...restToolbarSettings } = toolbarSettings;

  return (
    <ToolbarStateContext.Provider
      value={React.useMemo(
        () => ({
          resolvedToolbarSettings,
          ...restToolbarSettings,
        }),
        [
          resolvedToolbarSettings,
          restToolbarSettings.staticToolbarAlignment,
          restToolbarSettings.textToolbarContainer,
          restToolbarSettings.useStaticTextToolbar,
          selectedNodes,
        ]
      )}
      onSelectorContextValue={onSelectorContextValue}
    >
      {children}
    </ToolbarStateContext.Provider>
  );
};

export const useToolbarSettings = <T extends unknown>(
  selector: (s: ToolbarState) => T,
  trackingString?: string
): T => {
  return useContextSelector(ToolbarStateContext, selector, Object.is, trackingString);
};

export const getToolbarSettings =
  <T extends ToolbarType>(toolbarType: T) =>
  (state: ToolbarState): Extract<ToolbarSettingsFunctions, { name: T }> | undefined => {
    const settings = state.resolvedToolbarSettings.find(setting => setting.name === toolbarType) as
      | Extract<ToolbarSettingsFunctions, { name: T }>
      | undefined;
    return settings;
  };

export const getIsStaticTextToolbarEnabled = (state: ToolbarState): boolean =>
  typeof state.useStaticTextToolbar === 'boolean'
    ? state.useStaticTextToolbar
    : typeof state.useStaticTextToolbar === 'object'
      ? !state.useStaticTextToolbar.disabled
      : false;

const useResolveToolbarSettings = (toolbarSettings: ToolbarSettings) => {
  const plugins = useContext(PluginsContext);

  return React.useMemo(() => {
    const pluginButtons = plugins.getAddButtons().map(b => ({
      buttonSettings: { name: b.id, toolbars: b.toolbars },
      component: b.icon,
      blockType: 'node',
    }));

    const defaultSettings = getDefaultToolbarSettings({
      textButtons,
      pluginButtons,
      pluginButtonNames: supportedInsertButtonNames,
    });

    const customSettings =
      toolbarSettings?.getToolbarSettings?.({
        textButtons,
        pluginButtons,
        pluginButtonNames: supportedInsertButtonNames,
      }) || [];

    return mergeToolbarSettings({ defaultSettings, customSettings });
  }, [plugins, toolbarSettings]);
};
