import type { QueryItem } from '../../types.js';

const NAME = 'activeTextStyles';
const activeTextStylesFn: QueryItem =
  ({ editorQuery }) =>
  (textStyleName: $TSFixMe) => {
    const selectedNodesTextStyles = editorQuery
      .selection()
      .doc.descendants((node: $TSFixMe) => node.isTextBlock())
      .map((node: $TSFixMe) => {
        return editorQuery.styles().getComputedTextStyle(node, textStyleName);
      });

    const activeTextStyles = selectedNodesTextStyles.filter(isDefined);

    return activeTextStyles;
  };

const isDefined = <T>(x: T | null | undefined): x is T => x !== undefined && x !== null;

export const activeTextStyles = { NAME, query: activeTextStylesFn };
