import type {
  AddButton,
  EditorPlugin as EditorPluginType,
  FloatingToolbarButton,
  LegacyEditorPluginConfig,
  PluginExports,
  QuickAction,
  RicosExtension,
  RicosServices,
  TextButton,
} from './../ricos-types/index.js';

import type { EditorPlugins, PluginServices } from './editor-plugins.js';
import { RicosPluginToolbar } from './plugin-toolbar.js';

export class EditorPlugin {
  private readonly plugin: EditorPluginType;

  private addButtons?: AddButton[];

  private textButtons?: TextButton[];

  private toolbars?: RicosPluginToolbar[];

  private floatingToolbarButton?: FloatingToolbarButton;

  private exports?: Partial<PluginExports>;

  services: PluginServices;

  static of(
    plugin: EditorPluginType,
    services: PluginServices & { plugins?: EditorPlugins }
  ): EditorPlugin {
    return new EditorPlugin(plugin, services);
  }

  private constructor(plugin: EditorPluginType, services: PluginServices) {
    this.plugin = plugin;
    this.services = services;
  }

  private initAddButtons() {
    if (this.plugin.getAddButtons) {
      this.addButtons = this.plugin.getAddButtons(
        this.plugin.config,
        this.services as RicosServices
      );
    }
  }

  private initTextButtons() {
    if (this.plugin.textButtons) {
      this.textButtons = this.plugin.textButtons;
    }
  }

  private initPluginToolbar() {
    const toolbar = this.plugin.toolbar;
    if (!toolbar) {
      return;
    }

    this.toolbars = toolbar.names.map(name => {
      const ricosPluginToolbar = RicosPluginToolbar.of(
        toolbar,
        name,
        this.services as RicosServices,
        this.plugin.config
      );

      return ricosPluginToolbar;
    });
  }

  private initFloatingToolbarButton() {
    if (this.plugin.floatingToolbarButton) {
      this.floatingToolbarButton = this.plugin.floatingToolbarButton;
    }
  }

  private initExports() {
    if (this.plugin.exports) {
      this.exports = this.plugin.exports;
    }
  }

  register() {
    this.plugin.shortcuts?.map(shortcut => this.services.shortcuts.register(shortcut));
    this.initAddButtons();
    this.initTextButtons();
    this.initPluginToolbar();
    this.initFloatingToolbarButton();
    this.initExports();
  }

  unregister() {
    this.plugin.shortcuts?.forEach(shortcut => this.services.shortcuts.unregister(shortcut));
    this.floatingToolbarButton = undefined;
    this.exports = undefined;
  }

  getType(): string {
    return this.plugin.type;
  }

  getTiptapExtensions() {
    return (this.plugin as EditorPluginType).tiptapExtensions?.map(
      (extension): RicosExtension => ({
        ...extension,
        settings: this.getConfig(),
      })
    );
  }

  getConfig(): LegacyEditorPluginConfig {
    return this.plugin.config;
  }

  getTextButtons(): TextButton[] {
    return this.textButtons || [];
  }

  getQuickActions(): QuickAction[] {
    return (
      this.plugin.getQuickActions?.({
        pluginServices: this.services,
        config: this.plugin.config,
      }) || []
    );
  }

  getAddButtons() {
    return this.addButtons || [];
  }

  getToolbars() {
    return this.toolbars || [];
  }

  getFloatingToolbarButton() {
    return this.floatingToolbarButton || null;
  }

  getExports() {
    return this.exports || {};
  }

  getProvider() {
    return this.plugin.Provider || null;
  }

  getGlobalComponent() {
    return this.plugin.GlobalComponent || null;
  }

  equals(plugin: EditorPlugin) {
    return this.plugin.type === plugin.getType();
  }
}
