import type {
  Decoration,
  Decoration_Type,
  Node,
  Node_Type,
} from './../ricos-schema/next-schema/index.js';

export type { Node as ProseNode } from './../tiptap/pm/model.js';

export type PmJson = {
  type?: string;
  attrs?: Record<string, any>;
  content?: PmNodeJson[];
  marks?: PmMarkJson[];
  text?: string;
  [key: string]: any;
};
export type PmNodeJson = PmJson & {
  type: string;
};

export type PmMarkJson = {
  type: string;
  attrs?: Record<string, any>;
  [key: string]: any;
};

export type PmNodeConverter = {
  toPm: {
    types: Node_Type[];
    convert: (node: Node, visit?: (node: Node) => PmJson[]) => PmNodeJson;
  };
  fromPm: {
    types: string[];
    convert: (node: PmNodeJson, visit?: (node: PmNodeJson) => Node[]) => Node | undefined;
  };
};

// Resolves a Node_Type to its specific node type via the Node discriminated union.
// Falls back to Node for Node_Type values not present in the union.
type NodeByType<T extends Node_Type> =
  Extract<Node, { type: T }> extends never ? Node : Extract<Node, { type: T }>;

// NOTE: Do not switch this to `<const T extends Node_Type>` — `const` type
// parameters require TypeScript >= 5.0 and some consumers of this package are
// still on TypeScript 4.9. Because `T` is constrained to a string enum union,
// TypeScript already narrows it to the literal element type at call sites like
// `types: [Node_Type.PARAGRAPH]`, so `NodeByType<T>` in the `convert` callback
// still resolves to the specific node variant without `const`.
export const definePmNodeConverter = <T extends Node_Type>(converter: {
  toPm: {
    types: T[];
    convert: (node: NodeByType<T>, visit?: (node: Node) => PmNodeJson[]) => PmNodeJson;
  };
  fromPm: {
    types: string[];
    convert: (node: PmNodeJson, visit?: (node: PmNodeJson) => Node[]) => Node | undefined;
  };
}): PmNodeConverter => converter as unknown as PmNodeConverter;

export type PmMarkConverter = {
  toPm: {
    type: Decoration_Type;
    convert: (decoration: Decoration) => PmMarkJson | undefined;
  };
  fromPm: {
    type: string;
    convert: (mark: PmMarkJson) => Decoration[];
  };
};
