import type {
  IToolbarItemConfigTiptap,
  RicosServices,
  TFunction,
  ToolbarButton,
  ToolbarButtonTooltip,
} from './../ricos-types/index.js';
import { getNodeInSelection } from './../_shared/resolvers/get-node-in-selection.js';
import { isAlwaysVisible } from './../_shared/resolvers/is-always-visible.js';

/**
 * Represents plugin toolbar button
 *
 *
 * @export
 * @class PluginToolbarButton
 */
export class RicosPluginToolbarButton {
  button: ToolbarButton;

  services: RicosServices;

  private constructor(button: ToolbarButton, services: RicosServices) {
    this.button = button;
    this.services = services;
  }

  static of(button: ToolbarButton, services: RicosServices) {
    return new RicosPluginToolbarButton(button, services);
  }

  getButton(): ToolbarButton {
    return { ...this.button };
  }

  equals(button: RicosPluginToolbarButton): boolean {
    return this.button.id === button.getButton().id;
  }

  toToolbarItemConfig(): IToolbarItemConfigTiptap {
    const attributeResolvers = {
      visible: isAlwaysVisible,
      selectedNode: getNodeInSelection,
      ...this.button.attributes,
    };

    if (this.button.type === 'separator') {
      return {
        id: this.button.id,
        type: 'separator',
        presentation: {
          icon: this.button.icon,
        },
        attributes: attributeResolvers,
        commands: {},
      };
    }

    if (this.button.type === 'color') {
      const { command } = this.button;

      return {
        id: this.button.id,
        type: 'color',
        presentation: {
          tooltip: resolveTooltip(this.button.tooltip, this.services.t),
          dataHook: this.button.dataHook,
        },
        attributes: attributeResolvers,
        commands: {
          click:
            ({ publicCommands, tiptapEditor, attributes }) =>
            args => {
              return command({
                referenceElement: args?.referenceElement ?? args?.target,
                tiptapEditor,
                publicCommands,
                attributes,
                modals: this.services.modals,
                getComponentProps: undefined,
                ...args,
              });
            },
        },
      };
    }

    const { id, type, tooltip, dataHook, command } = this.button;

    const publishPluginToolbarClick = (args: $TSFixMe, node: $TSFixMe) => {
      const { value } = args || {};
      node && //temporary fix for table! (table hasn't node as attrs)
        this.services.pluginsEvents.publishPluginToolbarClick({
          pluginId: node.type.name,
          nodeId: node.attrs.id,
          buttonName: this.button.id,
          value,
        });
    };

    return {
      id,
      type,
      presentation: {
        tooltip: resolveTooltip(tooltip, this.services.t),
        label: this.button.label ? this.services.t(this.button.label) : undefined,
        dataHook,
        icon:
          'getIcon' in this.button
            ? this.button.getIcon?.({
                services: this.services,
                attributes: getResolvedAttributes(attributeResolvers, this.services),
              })
            : this.button.icon,
      },
      attributes: attributeResolvers,
      commands: {
        click:
          ({ publicCommands, tiptapEditor, attributes }) =>
          args => {
            const node = attributes.selectedNode;
            const returnValue = command({
              referenceElement: args?.referenceElement ?? args?.target,
              tiptapEditor,
              publicCommands,
              attributes,
              modals: this.services.modals,
              getComponentProps:
                'getComponentProps' in this.button ? this.button.getComponentProps : undefined,
              ...args,
            });
            publishPluginToolbarClick(args, node);
            return returnValue;
          },
      },
    };
  }

  getRenderer() {
    const { id, renderer } = this.button;
    return {
      [id]: renderer,
    };
  }
}

// String tooltips are translation keys, resolved here at construction time.
// Function tooltips depend on runtime state (isActive) so they're passed through
// untouched — the renderer invokes them and translates the result.
const resolveTooltip = (tooltip: ToolbarButtonTooltip, t: TFunction) =>
  typeof tooltip === 'function' ? tooltip : t(tooltip || '');

const getResolvedAttributes = (attributeResolvers: any, services: any) =>
  Object.keys(attributeResolvers)
    .map(attributeName => {
      return {
        attributeName,
        attribute: services.content.resolve(attributeResolvers[attributeName]),
      };
    })
    .reduce((acc, { attributeName, attribute }) => {
      return {
        ...acc,
        [attributeName]: attribute,
      };
    }, {});
