import React from 'react';

import type { EditorPlugins } from './editor-plugins.js';

type PluginProvidersProps = {
  plugins: EditorPlugins;
  children: React.ReactNode;
};

export const PluginProviders: React.FC<PluginProvidersProps> = ({ plugins, children }) => {
  const providers = plugins.getPluginProviders();

  if (providers.length === 0) {
    return <>{children}</>;
  }

  return providers.reduce(
    (wrappedChildren, Provider) => <Provider plugins={plugins}>{wrappedChildren}</Provider>,
    children
  );
};
