import { flow } from 'fp-ts-esm/function';

import type { PmConverters } from './../pm-converters/collect.js';
import type { PmJson } from './../pm-converters/types.js';
import { isRichContentEmpty } from './../ricos-content/index.js';
import { RichContent } from './../ricos-schema/legacy/wix/rich_content/v1/index.js';
import type { JSONContent } from './../tiptap/core/index.js';
import type { Fragment } from './../tiptap/pm/model.js';
import { getEmptyContent } from './../editor-common/index.js';

import type { RicosEditor } from './ricos-editor.js';

export class RicosSchema {
  private schema: RichContentSchema;

  private initialContent: JSONContent;

  private initialTiptapContent: Fragment | undefined;

  private editor?: RicosEditor;

  constructor(
    initialContent: RichContent | undefined,
    converters: PmConverters,
    shouldNormalizeRichContent: boolean = true
  ) {
    this.initialContent = converters.toPm(
      initialContent?.nodes?.length ? initialContent : (getEmptyContent() as $TSFixMe)
    );
    this.schema = new RichContentSchema(converters, shouldNormalizeRichContent);
  }

  setEditor(editor: RicosEditor): void {
    this.initialTiptapContent = editor.adapter.tiptapEditor.state.doc.content;
    this.editor = editor;
    this.schema.setEditor(editor);
  }

  setContent(content: RichContent): void {
    this.schema.setContent(content);
  }

  getContent = (): RichContent => {
    return this.schema.getContent();
  };

  getTiptapContent(): JSONContent {
    if (!this.editor) {
      return this.initialContent;
    }
    return this.editor.adapter.tiptapEditor.getJSON();
  }

  getID(): string {
    return this.schema.getID();
  }

  isContentChanged(): boolean {
    const editorContent = this.editor?.adapter.tiptapEditor.state.doc.content;
    return !!editorContent && !this.initialTiptapContent?.eq(editorContent);
  }

  isEmpty(): boolean {
    return this.schema.isEmpty();
  }
}

export class RichContentSchema {
  private editor!: RicosEditor;

  private converters!: PmConverters;

  private shouldNormalizeRichContent: boolean;

  constructor(converters: PmConverters, shouldNormalizeRichContent: boolean = true) {
    this.converters = converters;
    this.shouldNormalizeRichContent = shouldNormalizeRichContent;
  }

  setEditor(editor: RicosEditor) {
    this.editor = editor;
  }

  setContent(content: RichContent): void {
    const jsonContent = this.converters.toPm(content as $TSFixMe);
    this.editor.adapter.setTiptapContent(jsonContent);
  }

  getContent(): RichContent {
    const tiptapContent = this.editor?.adapter.tiptapEditor.getJSON();
    const content = this.converters.fromPm(tiptapContent as PmJson) as RichContent;
    return this.shouldNormalizeRichContent
      ? (normalizeRichContent(content) as RichContent)
      : content;
  }

  getID(): string {
    return this.getContent().metadata?.id as string;
  }

  isEmpty(): boolean {
    const content = this.getContent();
    return isRichContentEmpty(content);
  }
}

const normalizeRichContent = flow(RichContent.fromJSON, RichContent.toJSON);
