/* oxlint-disable brace-style */
import type { RicosEditorProps } from './../ricos-common/index.js';
import type { PmContentContextType } from './../ricos-context/pm-content-context.js';
import type { SelectionContextType } from './../ricos-context/selection-context.js';
import type { ToolbarState } from './../ricos-context/toolbar-context.js';
import type { ModalState } from './../ricos-modals/modal-service.js';
import type {
  EditorEventSource,
  EventSource,
  IRicosEditor,
  PolicySubscriber,
  PublisherProvider,
  RicosServices,
  SubscriptorProvider,
} from './../ricos-types/index.js';
import type { SelectorContextValue } from './../_shared/use-context-selector.js';
import type { InlineAiContextType } from './../plugin-inline-ai/inline-ai-context.js';
import type { TiptapAdapter } from './../tiptap-editor/components/rich-content-adapter.js';
import { initializeTiptapAdapter } from './../tiptap-editor/index.js';

type Topics = [
  'ricos.editor.instance.loaded',
  'ricos.editor.instance.error',
  'ricos.editor.functionality.firstEdit',
  'ricos.editor.content.saved',
];

const topics: Topics = [
  'ricos.editor.instance.loaded',
  'ricos.editor.instance.error',
  'ricos.editor.functionality.firstEdit',
  'ricos.editor.content.saved',
];

type UploadTopics = [
  'ricos.upload.functionality.uploadStarted',
  'ricos.upload.functionality.uploadFinished',
];

const UPLOAD_TOPICS: UploadTopics = [
  'ricos.upload.functionality.uploadStarted',
  'ricos.upload.functionality.uploadFinished',
];

export class RicosEditor
  implements IRicosEditor, EventSource<Topics>, PolicySubscriber<UploadTopics>, EditorEventSource
{
  private tiptapAdapter: TiptapAdapter;

  id = 'ricos-editor';

  constructor(
    editorProps: RicosEditorProps,
    services: Omit<RicosServices, 'editor' | 'zIndexService'>,
    isDebugMode = false,
    getToolbarStateSelectorContextValue: () => SelectorContextValue<ToolbarState>,
    getSelectionSelectorContextValue: () => SelectorContextValue<SelectionContextType>,
    getModalStateSelectorContextValue: () => SelectorContextValue<ModalState>,
    getPmContentSelectorContextValue: () => SelectorContextValue<PmContentContextType>,
    getInlineAiStateSelectorContextValue: () => SelectorContextValue<InlineAiContextType>
  ) {
    this.tiptapAdapter = initializeTiptapAdapter(
      editorProps,
      services,
      isDebugMode,
      getToolbarStateSelectorContextValue,
      getSelectionSelectorContextValue,
      getModalStateSelectorContextValue,
      getPmContentSelectorContextValue,
      getInlineAiStateSelectorContextValue
    );
  }

  topicsToPublish = topics;

  topicsToSubscribe = UPLOAD_TOPICS;

  publishers!: PublisherProvider<Topics>;

  subscriptors!: SubscriptorProvider<UploadTopics>;

  publishLoaded() {
    return this.publishers
      .byTopic('ricos.editor.instance.loaded')
      .publish({ msg: '🖖 editor mounted' });
  }

  publishFirstEdit() {
    return this.publishers
      .byTopic('ricos.editor.functionality.firstEdit')
      .publishOnce({ msg: '📝 first content edit' });
  }

  publishError(error: any, errorInfo: any): boolean {
    return this.publishers.byTopic('ricos.editor.instance.error').publish({ error, errorInfo });
  }

  publishContentSaved(): boolean {
    return this.publishers
      .byTopic('ricos.editor.content.saved')
      .publish({ msg: '💾 content saved' });
  }

  get adapter() {
    return this.tiptapAdapter;
  }

  getPublicCommands = () => this.tiptapAdapter.getEditorCommands();
}
