import { pipe } from 'fp-ts-esm/function';

import type { PmConverters } from './../pm-converters/collect.js';
import { collectPmConverters } from './../pm-converters/collect.js';
import { commonPluginConfig, commonPlugins } from './../ricos-common-plugins/index.js';
import type { RicosEditorProps } from './../ricos-common/index.js';
import type { IEditorQuery } from './../ricos-content-query/index.js';
import { editorQueryCreator } from './../ricos-content-query/index.js';
import type { DevService, GeneralContext } from './../ricos-context/index.js';
import type { PmContentContextType } from './../ricos-context/pm-content-context.js';
import type { SelectionContextType } from './../ricos-context/selection-context.js';
import type { ToolbarState } from './../ricos-context/toolbar-context.js';
