import { RicosEditor } from './ricos-editor.js';
import { RicosSchema } from './ricos-schema.js';

export class RicosOrchestrator {
  private readonly editorProps: RicosEditorProps & {
    debugMode?: DebugMode[];
    pluginConfig?: LegacyEditorPluginConfig;
    helpers?: Helpers;
    biLogger?: { logV2: (params: any) => void };
  };

  private readonly pluginsMap: Partial<Record<string, EditorPluginCreator>>;

  /** Mutable ref updated by FullRicosEditor when BI helpers load asynchronously. */
  readonly biHelpersRef: { current: Partial<BICallbacks> } = { current: {} };

  private updateService!: UpdateService;

  private readonly events: RicosEvents;

  private readonly pluginsEvents: PluginsEvents;

  private readonly modals: ModalService;

  private readonly styles: RicosStyles;

  private readonly shortcuts: EditorKeyboardShortcuts;

  private readonly plugins: EditorPlugins;

  private readonly uploadService: IUploadService;

  private readonly t: TFunction;

  private readonly content: Content<Node[]>;

  private readonly editor: RicosEditor;

  private readonly editorQuery: IEditorQuery;

  private readonly context: Omit<GeneralContext, 'theme'>;

  private readonly schema: RicosSchema;

  private readonly zIndexService: ZIndexService;

  private readonly pluginExports: Partial<PluginExports>;

  private readonly converters: PmConverters;

  private readonly devService: DevService;

  inlineAiService: Partial<InlineAiService> = {};

  inlineAiStateSelectorContextValue: SelectorContextValue<any> | undefined = undefined;

  toolbarStateSelectorContextValue: SelectorContextValue<ToolbarState> | undefined = undefined;

  selectionSelectorContextValue: SelectorContextValue<SelectionContextType> | undefined = undefined;

  modalStateSelectorContextValue: SelectorContextValue<ModalState> | undefined = undefined;

  pmContentSelectorContextValue: SelectorContextValue<PmContentContextType> | undefined = undefined;

  private readonly wixInstance: WixInstanceService;

  private readonly makeRequestService: RequestService;

  constructor({
    editorProps,
    t,
    platform,
    modalService,
    devService,
    wixInstance,
    makeRequestService,
    pluginsMap,
  }: {
    editorProps: RicosEditorProps & {
      debugMode?: DebugMode[];
      jsdomMode?: boolean;
      pluginConfig?: LegacyEditorPluginConfig;
      helpers?: Helpers;
      biLogger?: { logV2: (params: any) => void };
    };
    t: TFunction;
    platform: Platform;
    modalService: ModalService;
    devService: DevService;
    wixInstance: WixInstanceService;
    makeRequestService: RequestService;
    pluginsMap: Partial<Record<EditorPluginOptions['type'], EditorPluginCreator>>;
  }) {
    this.t = t;
    this.editorProps = editorProps;

    this.devService = devService;

    this.wixInstance = wixInstance;

    this.makeRequestService = makeRequestService;
    this.pluginsMap = pluginsMap;

    this.styles = new RicosStyles();

    const getEditorQuery = (): IEditorQuery => {
      return this.editorQuery;
    };

    this.converters = collectPmConverters(collectAllPlugins(this.editorProps, pluginsMap));

    this.content = Content.create<Node[]>([], {
      styles: this.styles,
      converters: this.converters,
      getEditorQuery,
      editor: null,
      modals: modalService,
    });

    const isMobile = editorProps.isMobile || false;

    this.context = {
      t,
      debugMode: editorProps.debugMode || [],
      isMobile,
      languageDir: getLangDir(editorProps.locale),
      locale: editorProps.locale || 'en',
      localeContent: editorProps.localeContent || editorProps.locale || 'en',
      experiments: editorProps.experiments || {},
      platform: platform || 'macOs',
      content: this.content,
      jsdomMode: editorProps.jsdomMode ?? false,
      environment: editorProps.environment || 'liveSite',
      tabIndex: -1,
      portal: null,
      lastInteraction: null,
      tabFocusBehavior: editorProps.tabFocusBehavior || 'edit',
    };

    this.updateService = createUpdateService();
    this.events = new RicosEvents(
      (editorProps.debugMode?.includes('events') || editorProps.debugMode?.includes('all')) ?? false
    );

    this.uploadService = new UploadService(this.updateService);

    this.modals = modalService;

    this.shortcuts = new EditorKeyboardShortcuts(this.modals, {
      isDebugMode:
        (editorProps.debugMode?.includes('shortcuts') || editorProps.debugMode?.includes('all')) ??
        false,
    });

    this.pluginsEvents = new PluginsEvents();

    this.schema = new RicosSchema(
      editorProps.content,
      this.converters,
      editorProps.shouldNormalizeRichContent ?? true
    );

    const focusShortcut: KeyboardShortcut = {
      name: 'EnterToolbar',
      description: 'ShortcutsSheet_ToolbarNavigation_EnterToolbar',
      group: 'ShortcutsSheet_Section_ToolbarNavigation',
      keys: { macOs: 'Ctrl+T', windows: 'Alt+T' },
      command: ({ event }) => {
        event?.preventDefault();

        const focusFirstFocusableElement = (toolbarDataHook: string) => {
          const portalElement = this.context.portal || document;
          const toolbarElement = portalElement.querySelector(
            `[data-hook~=${toolbarDataHook}] [data-hook~=${TOOLBAR_VISIBLE}]`
          );
          const firstFocusableElement = toolbarElement?.querySelector(
            FOCUSABLE_SELECTOR
          ) as HTMLElement;
          firstFocusableElement?.focus();
        };

        focusFirstFocusableElement(FLOATING_FORMATTING_TOOLBAR);
        focusFirstFocusableElement(STATIC_TOOLBAR_DATA_HOOK);
        focusFirstFocusableElement(FLOATING_PLUGIN_TOOLBAR);
        return 'continue';
      },
      enabled: true,
      showInShortcutSheet: true,
    };

    this.shortcuts.register(focusShortcut);

    this.plugins = new EditorPlugins({
      modals: this.modals,
      uploadService: this.uploadService,
      updateService: this.updateService,
      shortcuts: this.shortcuts,
      t: this.t,
      content: this.content,
      styles: this.styles,
      pluginsEvents: this.pluginsEvents,
      context: this.context,
      schema: this.schema,
      converters: this.converters,
      devService,
      editorProps: this.editorProps,
      wixInstance,
      makeRequestService,
    });

    this.registerAllPlugins(commonPluginConfig);

    if (editorProps.keyboardShortcuts) {
      editorProps.keyboardShortcuts.map(shortcut =>
        this.shortcuts.mergeKeyboadShortcutProp(shortcut)
      );
    }

    this.editor = new RicosEditor(
      this.editorProps,
      {
        styles: this.styles,
        plugins: this.plugins,
        updateService: this.updateService,
        uploadService: this.uploadService,
        t: this.t,
        content: this.content,
        shortcuts: this.shortcuts,
        modals: this.modals,
        pluginsEvents: this.pluginsEvents,
        context: this.context,
        schema: this.schema,
        getEditorQuery,
        converters: this.converters,
        devService,
        editorProps: this.editorProps,
        wixInstance,
        makeRequestService,
        inlineAi: this.inlineAiService,
      },
      this.editorProps.debugMode?.includes('prosemirror') || editorProps.debugMode?.includes('all'),
      () => {
        if (!this.toolbarStateSelectorContextValue) {
          throw new Error('toolbarStateSelectorContextValue is not set');
        }
        return this.toolbarStateSelectorContextValue;
      },
      () => {
        if (!this.selectionSelectorContextValue) {
          throw new Error('selectionSelectorContextValue is not set');
        }
        return this.selectionSelectorContextValue;
      },
      () => {
        if (!this.modalStateSelectorContextValue) {
          throw new Error('modalStateSelectorContextValue is not set');
        }
        return this.modalStateSelectorContextValue;
      },
      () => {
        if (!this.pmContentSelectorContextValue) {
          throw new Error('pmContentSelectorContextValue is not set');
        }
        return this.pmContentSelectorContextValue;
      },
      () => {
        if (!this.inlineAiStateSelectorContextValue) {
          throw new Error('inlineAiStateSelectorContextValue is not set');
        }
        return this.inlineAiStateSelectorContextValue;
      }
    );

    this.plugins.setPublicCommands(this.editor.getPublicCommands());
    this.schema.setEditor(this.editor);
    this.content.update([], this.editor.adapter.tiptapEditor);

    this.updateService.setEditorCommands(this.editor.getPublicCommands());

    this.editorQuery = editorQueryCreator(
      this.editor.adapter.tiptapEditor,
      this.styles,
      this.converters
    );

    this.pluginExports = this.plugins.getExports();

    this.zIndexService = new ZIndexService(
      !!editorProps.isMobile,
      editorProps.theme?.settingsStyles
    );

    if (!isSSR()) {
      //@ts-ignore
      window.editorQuery = this.editorQuery;
      //@ts-ignore
      window.ricosOrchestrator = this;
    }

    // NOTE: this should run after entities initializations!
    this.orchestrateEvents();
  }

  // NOTE: it is crucual to keep the event registration/subsciption order to ensure their correct workflow
  private orchestrateEvents() {
    registerEventSources(this.events, [
      this.shortcuts,
      this.modals,
      this.editor as unknown as RicosEventSource,
      this.uploadService,
      this.pluginsEvents,
      this.styles,
    ] as RicosEventSource[]);
    registerEventSubscribers(this.events, [this.modals as unknown as RicosEventSubscriber]);
    registerEventSubscribers(this.events, [
      this.modals as unknown as RicosEventSubscriber,
      this.editor as unknown as RicosEventSubscriber,
      this.styles as unknown as RicosEventSubscriber,
      this.pluginsEvents as unknown as RicosEventSubscriber,
    ]);
    mapBiCallbacksToSubscriptions(this.biHelpersRef, this.events, this.schema);
  }

  setUpdateServiceDom(
    setErrorNotifier: () => INotifier,
    setFileInput: () => HTMLInputElement
  ): void {
    this.uploadService.setErrorNotifier(setErrorNotifier);
    this.uploadService.setHiddenInputElement(setFileInput);
  }

  getServices(): RicosServices {
    return {
      styles: this.styles,
      plugins: this.plugins,
      uploadService: this.uploadService,
      updateService: this.updateService,
      t: this.t,
      shortcuts: this.shortcuts,
      content: this.content,
      modals: this.modals,
      editor: this.editor,
      pluginsEvents: this.pluginsEvents,
      context: this.context,
      schema: this.schema,
      zIndexService: this.zIndexService,
      getEditorQuery: () => this.editorQuery,
      converters: this.converters,
      devService: this.devService,
      editorProps: this.editorProps,
      wixInstance: this.wixInstance,
      makeRequestService: this.makeRequestService,
      inlineAi: this.inlineAiService,
    };
  }

  getPluginExports(): Partial<PluginExports> {
    return this.pluginExports;
  }

  private registerAllPlugins(commonPluginConfig: LegacyEditorPluginConfig) {
    const helpersConfig = getHelpersConfig(this.editorProps);

    pipe(
      collectAllPlugins(this.editorProps, this.pluginsMap),
      EditorPlugins.mergeConfig(this.editorProps.pluginConfig),
      EditorPlugins.mergeConfig(commonPluginConfig),
      EditorPlugins.mergeConfig(helpersConfig),
      A.map((plugin: EditorPlugin) => this.plugins.register(plugin))
    );
  }

  setPortalRef(portal: RicosPortal) {
    this.context.portal = portal;
  }
}

const collectAllPlugins = (
  editorProps: RicosEditorProps,
  pluginsMap: Partial<Record<string, EditorPluginCreator>>
) => {
  const { plugins } = editorProps;
  const collectPluginsWithDependencies = (plugins: EditorPlugin[]): EditorPlugin[] =>
    plugins.flatMap(plugin => [
      plugin,
      ...(plugin.dependencies ? collectPluginsWithDependencies(plugin.dependencies) : []),
    ]);

  const allOptions = plugins || [];
  const commonOptions = allOptions.filter(isCommonPluginOptions);
  const pluginOptions = allOptions.filter(opt => !isCommonPluginOptions(opt));

  const resolvedPlugins = pluginOptions.map(options => {
    // Hidden passthrough: if the option is already a full EditorPlugin (has tiptapExtensions),
    // use it directly without looking up a creator
    if ('tiptapExtensions' in options) {
      return options as unknown as EditorPlugin;
    }
    const creator = pluginsMap[options.type];
    if (!creator) {
      logInvariant(new Error(`Unknown plugin type: ${options.type}. No resolver registered.`));
      return undefined;
    }
    return creator(options as any);
  });

  const collectedPlugins = collectPluginsWithDependencies([
    ...commonPlugins(editorProps, commonOptions),
    ...resolvedPlugins.filter((p): p is EditorPlugin => !!p),
  ]);
  return [...new Set(collectedPlugins)];
};
