/* oxlint-disable jsx-a11y/no-noninteractive-element-interactions */
/* oxlint-disable jsx-a11y/click-events-have-key-events */
/* oxlint-disable jsx-a11y/no-static-element-interactions */
import classNames from 'classnames';
import React, { useContext, useState } from 'react';

import { RicosContext } from './../../ricos-context/index.js';
import type { ModalProps } from './../../ricos-types/index.js';
import { FocusManager } from './../../_shared/focus-manager/focus-manager.js';
import { UiComponentsProvider } from './../../ui-components/index.js';

import styles from '../statics/styles/drawer-scss.js';

export const Drawer = ({
  children,
  closeModal,
  modalConfig: { positioning },
  zIndex,
}: ModalProps) => {
  const { jsdomMode, isMobile } = useContext(RicosContext);
  const [ref, setRef] = useState<HTMLDivElement | null>(null);
  const onModalClick = (e: $TSFixMe) => e.stopPropagation();
  const onOverlayClick = () => closeModal();
  const { placement } = positioning || {};

  return (
    <div onClick={onOverlayClick} className={styles.overlay} style={{ zIndex }}>
      <FocusManager
        focusTrapOptions={{
          returnFocusOnDeactivate: false,
        }}
        jsdomMode={jsdomMode}
      >
        <div
          tabIndex={0}
          onClick={onModalClick}
          className={classNames(
            styles.content,
            styles.contentBox,
            placement && styles[placementClassNameMapper[placement]],
            {
              [styles.mobile]: isMobile,
            }
          )}
          ref={setRef}
          role="dialog"
        >
          {ref && <UiComponentsProvider containerEl={ref}>{children}</UiComponentsProvider>}
        </div>
      </FocusManager>
    </div>
  );
};

const placementClassNameMapper: $TSFixMe = {
  right: 'drawerR',
  left: 'drawerL',
  top: 'drawerT',
  bottom: 'drawerB',
};
