import type {
  Decoration,
  RicosDocument,
  RicosDocumentNode,
} from './../ricos-schema/next-schema/index.js';
import type { EditorPluginConfig } from './../ricos-types/index.js';
import type { Attachment } from './../_shared/pm-node-types.js';
import type { RequestService } from './../_shared/request-service-provider/request-service-provider.js';

import type { AfterAiRegion, RangeAiRegion } from './ai-region-extension.js';

export const INLINE_AI_PLUGIN_TYPE = 'inline-ai';

// Lives here (not modal.tsx) so leaf modules like typing-panel.tsx can import
// it without creating an import cycle through the modal.
export const INLINE_AI_MODAL_ID = 'inline-ai';

export type InlinePromptFile = {
  fileUrl: string;
  mimeType: string;
};

export type InlineAiFile = InlinePromptFile & {
  fileName: string;
};

export type InlinePromptInterceptorResult = 'continue' | 'stop' | 'replace';

export type InlinePromptInterceptor = (
  prompt: string,
  selection: RicosDocumentNode[],
  files: InlinePromptFile[],
  invocationId?: string
) => InlinePromptInterceptorResult;

export type AiMessage = AiMessageInsert | AiMessageReplace | AiMessageText | AiMessageTheme;

export type DoPromptStreamArgs = {
  prompt: string;
  document: RicosDocument;
  selection: RicosDocumentNode[];
  makeRequest: RequestService['makeRequest'];
  metasiteId?: string;
  getCurrentTheme?: () => any;
  /** The session this run belongs to: the state-slice key, and what gets logged. */
  invocationId?: string;
  /**
   * Identifies this one execution attempt, and is what gets sent as the request's
   * idempotency key. Distinct from `invocationId` because a session can run more
   * than one execution — cancel returns it to 'typing' and the user resubmits —
   * while the server allows each key to execute at most once.
   */
  executionId: string;
  files?: InlineAiFile[];
  traceParams?: Record<string, string>;
  systemPromptId?: string;
};

export type DoPromptStream = (args: DoPromptStreamArgs) => AsyncGenerator<Chunk, any>;

export type AiMessageText = {
  type: 'text';
  subtype: 'explain' | 'summary' | 'error' | 'tool';
  text: string;
  from?: string;
  to?: string;
  completed?: boolean;
  toolParameters?: any;
};

export type AiMessageInsert = {
  type: 'insert';
  nodes: RicosDocumentNode[];
  after: string;
  completed: boolean;
  aiRegion?: AfterAiRegion;
  isRootLevel: boolean;
  viewBefore: boolean;
};

export type AiMessageReplace = {
  type: 'replace';
  nodes: RicosDocumentNode[];
  from: string;
  to: string;
  completed: boolean;
  aiRegion?: RangeAiRegion;
  originalNodesRef: { current?: RicosDocumentNode[] };
  isRootLevel: boolean;
  viewBefore: boolean;
};

export type AiMessageTheme = {
  type: 'theme';
  theme: any;
};

export type Chunk =
  | {
      chunk:
        | { type: 'UPDATE_DOCUMENT' }
        | { type: 'UPDATE_DOCUMENT_END' }
        | {
            type: 'ERROR';
            errorOptions: { text: string };
          }
        | {
            type: 'EXPLAIN';
            explainOptions: {
              text: string;
            };
          }
        | {
            type: 'SUMMARY';
            summaryOptions: {
              text: string;
            };
          }
        | {
            type: 'TOOL_USE';
            toolUseOptions: {
              toolName: string;
              parameters: any;
            };
          }
        | {
            type: 'INSERT';
            insertOptions: {
              after: string;
            };
          }
        | {
            type: 'INSERT_END';
          }
        | {
            type: 'REPLACE';
            replaceOptions: {
              from: string;
              to: string;
            };
          }
        | {
            type: 'REPLACE_END';
          }
        | {
            type: 'NODE';
            nodeOptions: {
              parent?: string;
              pending?: boolean;
              node: RicosDocumentNode;
            };
          }
        | {
            type: 'NODE_TEXT';
            nodeTextOptions: {
              parent: string;
              text: string;
              decorations: Decoration[];
            };
          }
        | { type: 'PATCH'; patchOptions: { node: RicosDocumentNode } }
        | { type: 'THEME'; themeOptions: { theme: any } }
        | MetadataChunk;
    }
  | {
      type: 'error';
      message: string;
      status?: number;
      applicationErrorCode?: string;
    };

export type MetadataChunk = {
  type: 'METADATA';
  metadataOptions: {
    microcentsSpent?: number;
    inputTokens?: number;
    outputTokens?: number;
    cacheCreationInputTokens?: number;
    cacheReadInputTokens?: number;
  };
};

// Full state includes all invocations
export type InlineAiFullState = {
  invocations: Record<string, InlineAiState>;
  /**
   * The selection an intercepted prompt was submitted over, as `from-to`.
   * AiSelectionTooltip keeps its pill hidden over exactly this range: the prompt
   * has already been handed off (in wixel, to the Aria chat panel), so re-offering
   * "press space to edit with AI" on the spot is noise. Cleared as soon as the
   * selection moves, so re-selecting the same range later gets the pill back.
   */
  submittedSelection?: string;
};

export type InlineAiService = {
  executePrompt?: (args: {
    prompt: string;
    selection: RicosDocumentNode[];
    document: RicosDocument;
    getCurrentTheme?: () => any;
    invocationId: string;
    files?: InlineAiFile[];
    onThemeChange?: (theme: any) => void;
    traceParams?: Record<string, string>;
    systemPromptId?: string;
  }) => void;
};

export type InlineAiState =
  | {
      type: 'typing';
      value: string;
      attachments?: Attachment[];
    }
  // 'pending' and 'streaming' are the states that mean a run is in flight, so they
  // are the ones that carry its executionId — see isExecutionCurrent. Every other
  // state carries none, which is what makes a cancelled run (back to 'typing')
  // stand down without any extra bookkeeping.
  | {
      type: 'pending';
      prompt: string;
      executionId: string;
      attachments?: Attachment[];
    }
  | {
      type: 'streaming';
      messages: AiMessage[];
      // for debugging
      chunks: Chunk[];
      prompt: string;
      executionId: string;
      attachments?: Attachment[];
    }
  | {
      type: 'error';
      error: { message: string; status?: number; applicationErrorCode?: string };
      messages: AiMessage[];
      chunks: Chunk[];
      prompt: string;
    }
  | {
      // after streaming completes, changes are auto-accepted and modal closes
      type: 'closed';
      messages: AiMessage[];
      // for debugging
      chunks: Chunk[];
      prompt: string;
    }
  | {
      // triggered externally when 'undo' is clicked after AI application
      // allows reviewing changes with pager, undo/redo per item, accept all/reject all
      type: 'preview';
      messages: AiMessage[];
      activeMessageIndex: number;
      // for debugging
      chunks: Chunk[];
      prompt: string;
    };

/** The states that mean an execution is in flight, i.e. the ones with an executionId. */
export type InlineAiRunningState = Extract<InlineAiState, { type: 'pending' | 'streaming' }>;

export const DEFAULT_TYPING_STATE: InlineAiState = { type: 'typing', value: '' };

// Lives here (not editor.tsx) so any plugin module can type its
// plugins.getConfig(INLINE_AI_PLUGIN_TYPE) read without importing the plugin
// creator. Re-exported from editor.tsx for external importers (ricos-types).
export type InlineAiPluginConfig = {
  type: 'inlineAi';
  interceptInlinePrompt?: InlinePromptInterceptor;
  onThemeChange?: (theme: any) => void;
  getCurrentTheme?: () => any;
  enableSelectionTooltip?: boolean;
  disableInlinePrompt?: boolean;
  aiProjectId?: string;
  useWixelWidgets?: boolean;
  generatingLabel?: string | null;
} & EditorPluginConfig;

/**
 * Fixed width of an inline-AI surface (the prompt panel, the response card),
 * rather than one tracking the text selection / editor width. Used by the
 * expanded AiSelectionTooltip and, in the wixel environment, by the modal.
 */
export const INLINE_AI_PANEL_WIDTH = 420;

/**
 * The gutter AriaSurfaceRow reserves beside the panel for the Aria avatar:
 * $aria-icon-size + $aria-icon-gap in aria-avatar-row.scss.
 */
export const ARIA_AVATAR_GUTTER = 32 + 12;

/**
 * The componentProps subset stamped by openInlineAIModal. `anchorToSelection`
 * is the single explicit signal that an opening is selection-anchored: while
 * such a modal is in its typing state (and the selection tooltip is enabled),
 * the expanded AiSelectionTooltip renders the prompt panel and the modal
 * paints nothing.
 */
export type InlineAiAnchorProps = {
  invocationId?: string;
  anchorToSelection?: boolean;
};

// Whether the expanded AiSelectionTooltip, rather than the modal itself, should paint the
// prompt input for this opening. Both sides call this on the same componentProps — the modal
// on its own props, the tooltip on what it reads back off the modal service — so neither has
// to tell the other what it decided.
export const shouldTooltipHostTyping = (
  componentProps: InlineAiAnchorProps | undefined,
  isMobile: boolean | undefined
): boolean =>
  Boolean(componentProps?.invocationId && componentProps?.anchorToSelection && !isMobile);

/**
 * Identifies a selection range for InlineAiFullState.submittedSelection. Lives here
 * so the writer (the typing panel, on submit) and the reader (AiSelectionTooltip)
 * cannot drift on the format.
 */
export const toSelectionKey = (selection: { from: number; to: number }): string =>
  `${selection.from}-${selection.to}`;
