/* oxlint-disable jsx-a11y/no-static-element-interactions */
import classNames from 'classnames';
import { emulateTab } from 'emulate-tab';
import type { FC } from 'react';
import React, { useContext, useEffect, useRef, useState } from 'react';
import ReactDOM from 'react-dom';

import {
  EditorContext,
  ModalServiceContext,
  RicosContext,
  ZIndexContext,
} from './../../ricos-context/index.js';
import type { IZindexLayer, Layout, LayoutTypes, Modal, ModalProps } from './../../ricos-types/index.js';
import { unreachable } from './../../_shared/uncreachable.js';

import { Dialog } from '../components/dialog.js';
import { Drawer } from '../components/drawer.js';
import { Floating } from '../components/floating.js';
import { Fullscreen } from '../components/fullscreen.js';
import classes from '../statics/styles/popper-scss.js';

type Props = {
  modalConfig: Modal;
  setModalRef: (ref: React.RefObject<any>) => void;
};

const layoutMapper: Record<LayoutTypes, React.ComponentType<ModalProps>> = {
  drawer: Drawer,
  fullscreen: Fullscreen,
  dialog: props => <Dialog {...props} />,
  floating: Floating,
  manual: ({ children }) => <>{children}</>,
};

const useForceUpdate = () => {
  const [_, setValue] = useState(0);
  return () => setValue(value => value + 1);
};

export const ModalPopper: FC<Props> = ({ modalConfig, setModalRef }: Props) => {
  const [isVisible, setIsVisible] = useState(false);
  const forceUpdate = useForceUpdate();
  const modalService = useContext(ModalServiceContext) || {};
  const zIndexService = useContext(ZIndexContext);
  const {
    adapter: { tiptapEditor },
  } = useContext(EditorContext);
  const { languageDir, portal, isMobile } = useContext(RicosContext);

  const stoppedKeyDownPropagationRef = useRef<string | null>(null);

  useEffect(() => {
    tiptapEditor.on('update', forceUpdate);

    return () => {
      tiptapEditor.off('update', forceUpdate);
    };
  }, []);

  useEffect(() => {
    setIsVisible(true);
  }, []);

  const closeModal = () => modalService?.closeModal?.(modalConfig.id);

  const onKeyDown = (e: React.KeyboardEvent<HTMLDivElement>) => {
    if (modalConfig.disableCloseOnEscape !== true && e.key === 'Escape') {
      e.preventDefault();

      if (modalConfig.onClickOutside && typeof modalConfig.onClickOutside === 'function') {
        modalConfig.onClickOutside(e as $TSFixMe);
        return;
      }

      e.stopPropagation();
      stoppedKeyDownPropagationRef.current = e.key;
      closeModal();
      return;
    }

    if (modalConfig.disableArrowNavigation) {
      return;
    }

    if (e.key === 'ArrowDown') {
      emulateTab();
      e.preventDefault();
    } else if (e.key === 'ArrowUp') {
      emulateTab.backwards();
      e.preventDefault();
    }
  };

  const onKeyUp = (e: React.KeyboardEvent<HTMLDivElement>) => {
    if (stoppedKeyDownPropagationRef.current === e.key) {
      e.stopPropagation();
      stoppedKeyDownPropagationRef.current = null;
    }
  };

  const resolveLayout = (layout: Layout): LayoutTypes => {
    if (typeof layout === 'object') {
      return isMobile ? layout.mobile : layout.desktop;
    }

    return layout;
  };

  const layout = resolveLayout(modalConfig.layout);

  const layoutToZIndex = (): IZindexLayer => {
    switch (layout) {
      case 'drawer':
        return 'DRAWER';
      case 'dialog':
      case 'fullscreen':
      case 'floating':
      case 'manual':
        return 'DIALOG';
      default:
        unreachable(layout);
        return 'DIALOG';
    }
  };

  const getZIndex = () => zIndexService.getZIndex(layoutToZIndex());

  const ModalLayout = layoutMapper[layout];

  const ModalComponent = modalConfig.Component;

  if (!portal) {
    return null;
  }

  return ReactDOM.createPortal(
    <div
      data-hook="modal-popper"
      dir={languageDir}
      onKeyDown={onKeyDown}
      onKeyUp={onKeyUp}
      className={classNames(classes.container, {
        [classes.transparent]: !isVisible && modalConfig.withTransition,
      })}
    >
      <ModalLayout closeModal={closeModal} modalConfig={modalConfig} zIndex={getZIndex()}>
        <ModalComponent
          ref={setModalRef}
          {...{ closeModal, modalConfig, zIndex: getZIndex() }}
          {...(modalConfig.componentProps || {})}
        />
      </ModalLayout>
    </div>,
    portal
  );
};
