import type { QueryItemCreator } from '../../types.js';

const NAME = 'isChildSingleTextBlock';
const isChildSingleTextBlockFn: QueryItemCreator =
  ({ editorQuery }) =>
  (nodeId: string) => {
    if (editorQuery.query.isMultipleSelection()) {
      return false;
    }
    const selectedNode = editorQuery
      .selection()
      .doc?.children?.[0]?.descendants(node => node.toNode()?.id === nodeId)[0];
    if (selectedNode?.children.length !== 1) {
      return false;
    }
    return !!selectedNode.children[0].isTextBlock();
  };

export const isChildSingleTextBlock = { NAME, query: isChildSingleTextBlockFn };
