import type { PmConverters } from './../../pm-converters/collect.js';
import type { RicosStyles } from './../../ricos-styles/index.js';
import type { Editor } from './../../tiptap/core/index.js';

import type { IEditorQuery } from '../types.js';
import { EditorQuery } from './editor-query.js';
import {
  activeDecorationsByTypeQuery,
  activeTextStylesQuery,
  isChildOfNode,
  isChildSingleTextBlock,
  isChildSingleTextBlockEmpty,
  isEmptyTextBlock,
  isListItem,
  isMultipleSelection,
  isNodeSelected,
  isOnlySlashInParagraph,
  isSingleRootTextBlock,
} from './queries/index.js';

const editorQueryCreator = (
  editor: Editor,
  ricosStyles: RicosStyles,
  converters: PmConverters
): IEditorQuery => {
  const editorQuery = new EditorQuery(editor, ricosStyles, converters);

  editorQuery.addQuery(activeDecorationsByTypeQuery.NAME, activeDecorationsByTypeQuery.query);
  editorQuery.addQuery(activeTextStylesQuery.NAME, activeTextStylesQuery.query);
  editorQuery.addQuery(isSingleRootTextBlock.NAME, isSingleRootTextBlock.query);
  editorQuery.addQuery(isMultipleSelection.NAME, isMultipleSelection.query);
  editorQuery.addQuery(isNodeSelected.NAME, isNodeSelected.query);
  editorQuery.addQuery(isChildSingleTextBlock.NAME, isChildSingleTextBlock.query);
  editorQuery.addQuery(isEmptyTextBlock.NAME, isEmptyTextBlock.query);
  editorQuery.addQuery(isListItem.NAME, isListItem.query);
  editorQuery.addQuery(isChildSingleTextBlockEmpty.NAME, isChildSingleTextBlockEmpty.query);
  editorQuery.addQuery(isChildOfNode.NAME, isChildOfNode.query);
  editorQuery.addQuery(isOnlySlashInParagraph.NAME, isOnlySlashInParagraph.query);

  editorQuery.query;
  return editorQuery;
};

export { editorQueryCreator };
