import type { Context } from 'react';
import React, { useContext, useEffect, useState } from 'react';

import type { SelectorContextValue } from './../_shared/use-context-selector.js';
import { createContext } from './../_shared/use-context-selector.js';
import type { Node as ProseMirrorNode, Mark } from './../tiptap/pm/model.js';
import type { Transaction } from './../tiptap/pm/state.js';

import { EditorContext } from './editor-context.js';

export type PmContentContextType = {
  content: ProseMirrorNode;
  storedMarks: readonly Mark[] | null;
  /**
   * Internal counter incremented when 'forceToolbarUpdate' transaction meta is set.
   * This forces context consumers (toolbars) to re-render on selection changes
   * that don't modify document content, such as completing a cell selection drag.
   * Needed for Wixel
   */
  _v: number;
};

const PmContentContext = createContext({} as PmContentContextType);

export const PmContentContextProvider = ({
  children,
  onSelectorContextValue,
}: {
  children: React.ReactNode;
  onSelectorContextValue: (
    selectorContextValue: SelectorContextValue<PmContentContextType>
  ) => void;
}) => {
  const {
    adapter: { tiptapEditor },
  } = useContext(EditorContext);

  const [content, setContent] = useState<ProseMirrorNode>(() => tiptapEditor.state.doc);
  const [storedMarks, setStoredMarks] = useState<readonly Mark[] | null>(
    () => tiptapEditor.state.storedMarks
  );
  const [v, setV] = useState(0);

  useEffect(() => {
    const updateContent = () => {
      setContent(tiptapEditor.state.doc);
      setStoredMarks(tiptapEditor.state.storedMarks);
    };

    const onTransaction = ({ transaction }: { transaction: Transaction }) => {
      if (transaction.storedMarksSet) {
        setStoredMarks(tiptapEditor.state.storedMarks);
      }
      if (transaction.getMeta('forceToolbarUpdate')) {
        setV(prev => prev + 1);
      }
    };

    tiptapEditor.on('update', updateContent);
    tiptapEditor.on('transaction', onTransaction);

    return () => {
      tiptapEditor.off('update', updateContent);
      tiptapEditor.off('transaction', onTransaction);
    };
  }, []);

  return (
    <PmContentContext.Provider
      value={React.useMemo(() => ({ content, storedMarks, _v: v }), [content, storedMarks, v])}
    >
      <SelectorContextValuePasser onSelectorContextValue={onSelectorContextValue} />
      {children}
    </PmContentContext.Provider>
  );
};

const SelectorContextValuePasser = ({
  onSelectorContextValue,
}: {
  onSelectorContextValue: (
    selectorContextValue: SelectorContextValue<PmContentContextType>
  ) => void;
}) => {
  const contextValue = useContext(
    PmContentContext as unknown as Context<SelectorContextValue<PmContentContextType>>
  );
  onSelectorContextValue(contextValue);
  return null;
};
