import type { QueryItem } from '../../types.js';

const NAME = 'isEmptyTextBlock';
const isEmptyTextBlockFn: QueryItem =
  ({ editorQuery }) =>
  () => {
    return (
      !!editorQuery.selection().doc?.children?.[0]?.isTextBlock() &&
      editorQuery.selection().doc?.children?.[0]?.node?.textContent === ''
    );
  };

export const isEmptyTextblock = { NAME, query: isEmptyTextBlockFn };
