import { Node_Type } from './../../../ricos-schema/next-schema/index.js';

import type { IEditorQuery, ITreeNodeQuery, QueryItem } from '../../types.js';

const NAME = 'isOnlySlashInParagraph';
const isOnlySlashInParagraphFn: QueryItem =
  ({ editorQuery }: { editorQuery: IEditorQuery }) =>
  () => {
    const { doc } = editorQuery.selection();
    let hasOnlySlashInParagraph = false;

    doc.descendants((node: ITreeNodeQuery) => {
      const ricosNode = node.toNode();
      if (
        node.isTextBlock() &&
        ricosNode?.nodes &&
        ricosNode.nodes.length === 1 &&
        ricosNode.nodes[0]?.type === Node_Type.TEXT &&
        ricosNode.nodes[0]?.textData?.text === '/'
      ) {
        hasOnlySlashInParagraph = true;
        return false;
      }
      return true;
    });

    return hasOnlySlashInParagraph;
  };

export const isOnlySlashInParagraph = { NAME, query: isOnlySlashInParagraphFn };
