/* oxlint-disable jsx-a11y/no-noninteractive-tabindex */
/* oxlint-disable jsx-a11y/click-events-have-key-events */
/* oxlint-disable jsx-a11y/no-static-element-interactions */
import classNames from 'classnames';
import type { ReactElement } from 'react';
import React, { useContext, useState } from 'react';

import { RicosContext } from './../../ricos-context/index.js';
import type { ModalProps } from './../../ricos-types/index.js';
import { FocusManager } from './../../_shared/focus-manager/focus-manager.js';
import { UiComponentsProvider } from './../../ui-components/index.js';

import styles from '../statics/styles/drawer-scss.js';

export const Dialog = ({ children, closeModal, zIndex, modalConfig }: ModalProps) => {
  const onModalClick = (e: $TSFixMe) => e.stopPropagation();
  const onOverlayClick = (e: $TSFixMe) => {
    if (modalConfig.onClickOutside && typeof modalConfig.onClickOutside === 'function') {
      modalConfig.onClickOutside(e);
      return;
    }
    closeModal();
  };
  const { jsdomMode } = useContext(RicosContext);
  const [ref, setRef] = useState<HTMLDivElement | null>(null);

  return (
    <FocusManager
      focusTrapOptions={{
        returnFocusOnDeactivate: false,
      }}
      jsdomMode={jsdomMode}
    >
      <div onClick={onOverlayClick} className={styles.overlay} style={{ zIndex }} tabIndex={0}>
        <div
          onClick={onModalClick}
          className={classNames(styles.content, styles.dialog)}
          ref={setRef}
        >
          {ref && (
            <UiComponentsProvider containerEl={ref}>
              {React.cloneElement(React.Children.only(children as ReactElement))}
            </UiComponentsProvider>
          )}
        </div>
      </div>
    </FocusManager>
  );
};
