/* eslint-disable max-depth */
import type {
  CreateRicosConversationRequest,
  RichContent,
} from '@wix/ambassador-ricos-v1-ricos-conversation/types';

import type { DoPromptStreamArgs } from './types.js';

type ApplicationError = { code?: string; description?: string };
type DoPromptStreamConfig = { aiProjectId?: string; useWixelWidgets?: boolean };

const MAX_CONVERSATION_COLOR_PALETTE_SIZE = 6;

const toStreamError = (args: {
  message?: string;
  applicationError?: ApplicationError;
  status?: number;
  statusFallback: string;
}) => {
  const message = args.message ?? args.applicationError?.description ?? args.statusFallback;
  return {
    type: 'error' as const,
    message,
    status: args.status,
    applicationErrorCode: args.applicationError?.code,
  } as any;
};

export const doPromptStreamOfStreams = async function* ({
  prompt,
  document,
  selection,
  makeRequest,
  getCurrentTheme,
  invocationId,
  executionId,
  files,
  traceParams,
  systemPromptId,
  aiProjectId,
  useWixelWidgets,
}: DoPromptStreamArgs & DoPromptStreamConfig) {
  try {
    const promptIdFromQuery = new URLSearchParams(window.location.search).get('ricosPromptId');
    const promptIdFromArg =
      systemPromptId && looksLikeUUID(systemPromptId) ? systemPromptId : undefined;
    const promptIdFromUrl =
      promptIdFromQuery && looksLikeUUID(promptIdFromQuery) ? promptIdFromQuery : undefined;
    const promptId = promptIdFromUrl ?? promptIdFromArg;

    const currentTheme = getCurrentTheme?.();
    const conversationTheme =
      currentTheme?.colorPalette?.length > MAX_CONVERSATION_COLOR_PALETTE_SIZE
        ? {
            ...currentTheme,
            colorPalette: currentTheme.colorPalette.slice(0, MAX_CONVERSATION_COLOR_PALETTE_SIZE),
          }
        : currentTheme;

    const baseUrl =
      typeof location !== 'undefined' && location.hostname === 'editor.wix.com'
        ? 'https://editor.wix.com/_api/ricos-ai-assistant/v1/ricos-conversations'
        : 'https://www.wixapis.com/ricos/v1/ricos-conversations';
    const conversationResponse = await makeRequest(`${baseUrl}/async`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        // Accept: 'application/x-ndjson',
      },
      body: JSON.stringify({
        ricosConversation: {
          promptId,
          message: prompt,
          theme: conversationTheme ?? undefined,
          returnMetadata: true,
          document: document as RichContent,
          documentSelection: { nodes: selection } as RichContent,
          files:
            files?.map(f => ({
              fileName: f.fileName || undefined,
              mimeType: f.mimeType || undefined,
              ...(f.fileUrl.includes('https://') ? { fileUrl: f.fileUrl } : { fileId: f.fileUrl }),
            })) ?? undefined,
          traceParams,
          projectId: useWixelWidgets
            ? '776d2a7f-5bc4-4ba0-b414-74cf7599cf15'
            : aiProjectId || undefined,
        },
        // Deliberately the executionId, not the session invocationId. The field is
        // documented as an "Idempotency key for at-most-once execution", so reusing
        // one value across a session's executions makes the second POST fail with
        // "Execution with idempotency key … is already done" — which is what
        // happens when a user cancels mid-stream and submits again.
        invocationId: executionId,
      } satisfies CreateRicosConversationRequest & { traceParams?: Record<string, string> }),
    }).catch(e => ({ ok: false, status: -1, statusText: e.message }) as Response);

    if (!conversationResponse.ok) {
      const errorBody = (await conversationResponse.json().catch(() => ({}))) as {
        message?: string;
        details?: { applicationError?: ApplicationError };
      };
      yield toStreamError({
        message: errorBody.message,
        applicationError: errorBody.details?.applicationError,
        status: conversationResponse.status,
        statusFallback: `Error: ${conversationResponse.status} ${conversationResponse.statusText}`,
      });
      return;
    }

    const requestId = conversationResponse.headers.get('x-wix-request-id');

    // eslint-disable-next-line no-console
    console.log(
      '\x1b[44m\x1b[97m RICOS PROMPT  \x1b[0m',
      prompt,
      // Both: invocationId is what useInlineAiState and the widget bridge are keyed
      // by, executionId is what the server logged this run under.
      `invocationId=${invocationId}`,
      `executionId=${executionId}`,
      `requestId=${requestId ?? ''}`
    );

    const result = await conversationResponse.json();

    let cursor: string = '';
    let emptyRetries = 0;

    while (true) {
      const chunkResponse = await makeRequest(
        `${baseUrl}/${result.conversationId}${cursor ? `?cursor=${cursor}` : ''}`,
        {
          method: 'GET',
          headers: {
            'Content-Type': 'application/json',
            Accept: 'application/x-ndjson',
          },
        }
      ).catch(e => ({ ok: false, status: -1, statusText: e.message }) as Response);

      const reader = chunkResponse.body?.getReader();
      if (!reader) {
        yield { type: 'error', message: 'Error: No chunk response body' } as any;
        return;
      }

      let receivedAnyData = false;
      for await (const chunk of readJsonStream(reader)) {
        receivedAnyData = true;
        if ('chunk' in chunk) {
          cursor = 'next' in chunk ? (chunk.next as string) : '';
          yield chunk as any;

          if (!cursor) {
            // no more chunks, the last chunk has not cursor
            return;
          }
        }
        if ('status' in chunk) {
          const errorChunk = chunk as {
            message?: string;
            status?: number;
            details?: { applicationError?: ApplicationError };
          };
          yield toStreamError({
            message: errorChunk.message,
            applicationError: errorChunk.details?.applicationError,
            status: errorChunk.status,
            statusFallback: `Error: ${errorChunk.status}`,
          });
          return;
        }
      }

      if (!receivedAnyData) {
        emptyRetries++;
        if (emptyRetries > 1) {
          yield {
            type: 'error',
            message: 'Error: No chunks received from AI service',
            status: -1,
          } as any;
          return;
        }
      } else {
        emptyRetries = 0;
      }
      // continue while
    }
  } catch (e: any) {
    yield { type: 'error', message: `Error: ${e.message}` } as any;
  }
};

async function* readJsonStream(
  reader: ReadableStreamDefaultReader<Uint8Array>
): AsyncGenerator<object, void, unknown> {
  const decoder = new TextDecoder('utf-8');
  let buffer = '';
  try {
    while (true) {
      const { done, value } = await reader.read();
      if (done) {
        break;
      }

      buffer += decoder.decode(value, { stream: true });

      const lines = buffer.split('\n');
      buffer = lines.pop() ?? ''; // incomplete line stays in buffer

      for (const line of lines) {
        if (line.trim()) {
          const json = JSON.parse(line);
          yield json;
        }
      }
    }

    if (buffer.trim()) {
      const json = JSON.parse(buffer);
      yield json;
    }
  } finally {
    reader.releaseLock();
  }
}

const looksLikeUUID = (str: string) =>
  /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/.test(str);
