import type { PmConverters } from './../pm-converters/collect.js';
import type { PmJson } from './../pm-converters/types.js';
import { extract } from './../ricos-content/lib/extract.js';
import type { Node } from './../ricos-schema/legacy/wix/rich_content/v1/index.js';
import type { Editor } from './../tiptap/react/index.js';

class GetContentExtractorError extends Error {}

export class RicosContentQueryService {
  private editor!: Editor;

  private converters!: PmConverters;

  public setEditor(editor: Editor, converters: PmConverters) {
    this.editor = editor;
    this.converters = converters;
  }

  public getContentExtractor(): ReturnType<typeof extract> {
    if (!this.editor) {
      throw new GetContentExtractorError(
        'getContentExtractor called without initialize editor instance (setEditor)'
      );
    }

    const tiptapContent = this.editor.getJSON();
    const richContent = this.converters.fromPm(tiptapContent as PmJson);
    const nodes = richContent.nodes as Node[];
    return extract(nodes ?? []);
  }
}
