/* oxlint-disable no-useless-constructor, eqeqeq */

// Because working with row and column-spanning cells is not quite
// trivial, this code builds up a descriptive structure for a given
// table node. The structures are cached with the (persistent) table
// nodes as key, so that they only have to be recomputed when the
// content of the table changes.
//
// This does mean that they have to store table-relative, not
// document-relative positions. So code that uses them will typically
// compute the start position of the table and offset positions passed
// to or gotten from this structure by that amount.
import type { Attrs, Node } from './../../tiptap/pm/model.js';

/**
 * @public
 */
export interface CellAttrs {
  colspan: number;
  rowspan: number;
  colwidth: number[] | null;
}

/**
 * @public
 */
export type ColWidths = number[];

/**
 * @public
 */
export type Problem =
  | {
      type: 'colwidth mismatch';
      pos: number;
      colwidth: ColWidths;
    }
  | {
      type: 'collision';
      pos: number;
      row: number;
      n: number;
    }
  | {
      type: 'missing';
      row: number;
      n: number;
    }
  | {
      type: 'overlong_rowspan';
      pos: number;
      n: number;
    }
  | {
      type: 'zero_sized';
    };

let readFromCache: (key: Node) => TableMap | undefined;
let addToCache: (key: Node, value: TableMap) => TableMap;

// Prefer using a weak map to cache table maps. Fall back on a
// fixed-size cache if that's not supported.
if (typeof WeakMap !== 'undefined') {
  // oxlint-disable-next-line
  let cache = new WeakMap<Node, TableMap>();
  readFromCache = key => cache.get(key);
  addToCache = (key, value) => {
    cache.set(key, value);
    return value;
  };
} else {
  const cache: (Node | TableMap)[] = [];
  const cacheSize = 10;
  let cachePos = 0;
  readFromCache = key => {
    for (let i = 0; i < cache.length; i += 2) {
      if (cache[i] == key) {
        return cache[i + 1] as TableMap;
      }
    }
  };
  addToCache = (key, value) => {
    if (cachePos === cacheSize) {
      cachePos = 0;
    }
    cache[cachePos++] = key;
    return (cache[cachePos++] = value);
  };
}

/**
 * @public
 */
export interface Rect {
  left: number;
  top: number;
  right: number;
  bottom: number;
}

/**
 * Describes a cell's placement in the table grid: its origin (row, col)
 * and how many rows/columns it spans.
 *
 * @public
 */
export type CellPlacement = {
  col: number;
  row: number;
  colspan: number;
  rowspan: number;
};

/**
 * A table map describes the structure of a given table. To avoid
 * recomputing them all the time, they are cached per table node. To
 * be able to do that, positions saved in the map are relative to the
 * start of the table, rather than the start of the document.
 *
 * @public
 */
export class TableMap {
  private _cellPlacements: Map<number, CellPlacement> | null = null;

  constructor(
    /**
     * The number of columns
     */
    public width: number,
    /**
     * The number of rows
     */
    public height: number,
    /**
     * A width * height array with the start position of
     * the cell covering that part of the table in each slot
     */
    public map: number[],
    /**
     * An optional array of problems (cell overlap or non-rectangular
     * shape) for the table, used by the table normalizer.
     */
    public problems: Problem[] | null
  ) {}

  private get cellPlacements(): Map<number, CellPlacement> {
    if (!this._cellPlacements) {
      this._cellPlacements = new Map();
      const seen = new Set<number>();
      for (let row = 0; row < this.height; row++) {
        for (let col = 0; col < this.width; col++) {
          const pos = this.map[row * this.width + col];
          if (seen.has(pos)) {
            continue;
          }
          seen.add(pos);
          let right = col + 1;
          while (right < this.width && this.map[row * this.width + right] === pos) {
            right++;
          }
          let bottom = row + 1;
          while (bottom < this.height && this.map[bottom * this.width + col] === pos) {
            bottom++;
          }
          this._cellPlacements.set(pos, {
            col,
            row,
            colspan: right - col,
            rowspan: bottom - row,
          });
        }
      }
    }
    return this._cellPlacements;
  }

  // Find the placement of the cell at the given position.
  findCell(pos: number): CellPlacement {
    const placement = this.cellPlacements.get(pos);
    if (!placement) {
      throw new RangeError(`No cell with offset ${pos} found`);
    }
    return placement;
  }

  // Iterate each unique cell exactly once, in reading order (left-to-right, top-to-bottom).
  forEachCell(callback: (cellPos: number, placement: CellPlacement) => void): void {
    this.cellPlacements.forEach((placement, pos) => callback(pos, placement));
  }

  // Find the left side of the cell at the given position.
  colCount(pos: number): number {
    for (let i = 0; i < this.map.length; i++) {
      if (this.map[i] == pos) {
        return i % this.width;
      }
    }
    throw new RangeError(`No cell with offset ${pos} found`);
  }

  // Find the next cell in the given direction, starting from the cell
  // at `pos`, if any.
  nextCell(pos: number, axis: 'horiz' | 'vert', dir: number): null | number {
    const { col, row, colspan, rowspan } = this.findCell(pos);
    if (axis == 'horiz') {
      if (dir < 0 ? col == 0 : col + colspan == this.width) {
        return null;
      }
      return this.map[row * this.width + (dir < 0 ? col - 1 : col + colspan)];
    } else {
      if (dir < 0 ? row == 0 : row + rowspan == this.height) {
        return null;
      }
      return this.map[col + this.width * (dir < 0 ? row - 1 : row + rowspan)];
    }
  }

  // Get the rectangle spanning the two given cells.
  rectBetween(...positions: [number, number, ...number[]]): Rect {
    const placements = positions.map(pos => this.findCell(pos));

    let bounds = placements.reduce(
      (acc, p) => ({
        top: Math.min(acc.top, p.row),
        left: Math.min(acc.left, p.col),
        bottom: Math.max(acc.bottom, p.row + p.rowspan),
        right: Math.max(acc.right, p.col + p.colspan),
      }),
      {
        top: placements[0].row,
        left: placements[0].col,
        bottom: placements[0].row + placements[0].rowspan,
        right: placements[0].col + placements[0].colspan,
      }
    );

    const visited = new Set<number>();
    const queue: number[] = [];

    for (let r = bounds.top; r < bounds.bottom; r++) {
      for (let c = bounds.left; c < bounds.right; c++) {
        const pos = this.map[r * this.width + c];
        if (!visited.has(pos)) {
          visited.add(pos);
          queue.push(pos);
        }
      }
    }

    while (queue.length) {
      const pos = queue.shift()!;
      const p = this.findCell(pos);

      // Expand bounds if this cell extends selection
      const newTop = Math.min(bounds.top, p.row);
      const newLeft = Math.min(bounds.left, p.col);
      const newBottom = Math.max(bounds.bottom, p.row + p.rowspan);
      const newRight = Math.max(bounds.right, p.col + p.colspan);

      const expanded =
        newTop < bounds.top ||
        newLeft < bounds.left ||
        newBottom > bounds.bottom ||
        newRight > bounds.right;

      if (expanded) {
        bounds = { top: newTop, left: newLeft, bottom: newBottom, right: newRight };

        // Add any cells newly within bounds
        for (let r = bounds.top; r < bounds.bottom; r++) {
          for (let c = bounds.left; c < bounds.right; c++) {
            const p = this.map[r * this.width + c];
            if (!visited.has(p)) {
              visited.add(p);
              queue.push(p);
            }
          }
        }

        if (
          bounds.top === 0 &&
          bounds.left === 0 &&
          bounds.bottom === this.height &&
          bounds.right === this.width
        ) {
          return bounds;
        }
      }
    }

    return bounds;
  }

  // Get the shallow rectangle spanning the two given cells.
  rectBetweenShallow(a: number, b: number): Rect {
    const pa = this.findCell(a);
    const pb = this.findCell(b);
    return {
      left: Math.min(pa.col, pb.col),
      top: Math.min(pa.row, pb.row),
      right: Math.max(pa.col + pa.colspan, pb.col + pb.colspan),
      bottom: Math.max(pa.row + pa.rowspan, pb.row + pb.rowspan),
    };
  }

  // Return the position of all cells that have the top left corner in
  // the given rectangle.
  cellsInRect(rect: Rect): number[] {
    const result: number[] = [];
    const seen: Record<number, boolean> = {};
    for (let row = rect.top; row < rect.bottom; row++) {
      for (let col = rect.left; col < rect.right; col++) {
        const index = row * this.width + col;
        const pos = this.map[index];

        if (seen[pos]) {
          continue;
        }
        seen[pos] = true;

        if (
          (col == rect.left && col && this.map[index - 1] == pos) ||
          (row == rect.top && row && this.map[index - this.width] == pos)
        ) {
          continue;
        }
        result.push(pos);
      }
    }
    return result;
  }

  // Return the position of all cells that overlap with the given rectangle,
  // including cells that start outside the rect but span into it.
  cellsOverlappingRect(rect: Rect): number[] {
    const result: number[] = [];
    const seen: Record<number, boolean> = {};
    for (let row = rect.top; row < rect.bottom; row++) {
      for (let col = rect.left; col < rect.right; col++) {
        const index = row * this.width + col;
        const pos = this.map[index];

        if (seen[pos]) {
          continue;
        }
        seen[pos] = true;

        result.push(pos);
      }
    }
    return result;
  }

  // Return the position at which the cell at the given row and column
  // starts, or would start, if a cell started there.
  positionAt(row: number, col: number, table: Node): number {
    for (let i = 0, rowStart = 0; ; i++) {
      const rowEnd = rowStart + table.child(i).nodeSize;
      if (i == row) {
        let index = col + row * this.width;
        const rowEndIndex = (row + 1) * this.width;
        // Skip past cells from previous rows (via rowspan)
        while (index < rowEndIndex && this.map[index] < rowStart) {
          index++;
        }
        return index == rowEndIndex ? rowEnd - 1 : this.map[index];
      }
      rowStart = rowEnd;
    }
  }

  // Find the table map for the given table node.
  static get(table: Node): TableMap {
    return readFromCache(table) || addToCache(table, computeMap(table));
  }

  // Build a table map from a grid of cells without ProseMirror nodes.
  // Each row is an array of physical cells with colspan/rowspan.
  // The map array stores sequential cell indices (0-based) instead of byte offsets.
  static fromGrid(rows: { colspan: number; rowspan: number }[][]): TableMap {
    const height = rows.length;
    if (height === 0) {
      return new TableMap(0, 0, [], null);
    }

    // Width is the widest row (not just row 0), so ragged content — e.g. a header
    // row missing a cell — doesn't under-size the grid and drop overflowing cells.
    const width = findGridWidth(rows);

    const map: number[] = new Array(width * height).fill(0);
    let problems: Problem[] | null = null;
    let cellIndex = 0;

    for (let row = 0; row < height; row++) {
      let mapPos = row * width;
      while (mapPos < (row + 1) * width && map[mapPos] !== 0) {
        mapPos++;
      }

      for (const cell of rows[row]) {
        // Skip past slots already filled by rowspan from above
        while (mapPos < (row + 1) * width && map[mapPos] !== 0) {
          mapPos++;
        }

        const col = mapPos % width;
        for (let h = 0; h < cell.rowspan; h++) {
          if (h + row >= height) {
            (problems || (problems = [])).push({
              type: 'overlong_rowspan',
              pos: cellIndex,
              n: cell.rowspan - h,
            });
            break;
          }
          const start = (row + h) * width + col;
          for (let w = 0; w < cell.colspan; w++) {
            if (map[start + w] === 0) {
              map[start + w] = cellIndex + 1; // +1 so 0 stays as "empty"
            } else {
              (problems || (problems = [])).push({
                type: 'collision',
                row,
                pos: cellIndex,
                n: cell.colspan - w,
              });
            }
          }
        }
        mapPos += cell.colspan;
        cellIndex++;
      }
    }

    // Shift all values down by 1 so cell indices are 0-based
    for (let i = 0; i < map.length; i++) {
      map[i]--;
    }

    return new TableMap(width, height, map, problems);
  }
}

// Compute a table map.
function computeMap(table: Node): TableMap {
  if (table.type.spec.tableRole != 'table') {
    throw new RangeError('Not a table node: ' + table.type.name);
  }
  const width = findWidth(table),
    height = table.childCount;
  const map = [];
  let mapPos = 0;
  let problems: Problem[] | null = null;
  const colWidths: ColWidths = [];
  for (let i = 0, e = width * height; i < e; i++) {
    map[i] = 0;
  }

  for (let row = 0, pos = 0; row < height; row++) {
    const rowNode = table.child(row);
    pos++;
    for (let i = 0; ; i++) {
      while (mapPos < map.length && map[mapPos] != 0) {
        mapPos++;
      }
      if (i == rowNode.childCount) {
        break;
      }
      const cellNode = rowNode.child(i);
      const { colspan, rowspan, colwidth } = cellNode.attrs;
      for (let h = 0; h < rowspan; h++) {
        if (h + row >= height) {
          (problems || (problems = [])).push({
            type: 'overlong_rowspan',
            pos,
            n: rowspan - h,
          });
          break;
        }
        const start = mapPos + h * width;
        for (let w = 0; w < colspan; w++) {
          if (map[start + w] == 0) {
            map[start + w] = pos;
          } else {
            (problems || (problems = [])).push({
              type: 'collision',
              row,
              pos,
              n: colspan - w,
            });
          }
          const colW = colwidth && colwidth[w];
          if (colW) {
            const widthIndex = ((start + w) % width) * 2,
              prev = colWidths[widthIndex];
            if (prev === null || (prev != colW && colWidths[widthIndex + 1] == 1)) {
              colWidths[widthIndex] = colW;
              colWidths[widthIndex + 1] = 1;
            } else if (prev == colW) {
              colWidths[widthIndex + 1]++;
            }
          }
        }
      }
      mapPos += colspan;
      pos += cellNode.nodeSize;
    }
    const expectedPos = (row + 1) * width;
    let missing = 0;
    while (mapPos < expectedPos) {
      if (map[mapPos++] == 0) {
        missing++;
      }
    }
    if (missing) {
      (problems || (problems = [])).push({ type: 'missing', row, n: missing });
    }
    pos++;
  }

  if (width === 0 || height === 0) {
    (problems || (problems = [])).push({ type: 'zero_sized' });
  }

  const tableMap = new TableMap(width, height, map, problems);
  let badWidths = false;

  // For columns that have defined widths, but whose widths disagree
  // between rows, fix up the cells whose width doesn't match the
  // computed one.
  for (let i = 0; !badWidths && i < colWidths.length; i += 2) {
    if (!(colWidths[i] === null) && colWidths[i + 1] < height) {
      badWidths = true;
    }
  }
  if (badWidths) {
    findBadColWidths(tableMap, colWidths, table);
  }

  return tableMap;
}

// Grid-input counterpart of `findWidth` for the schema/JSON path (`fromGrid`).
// `findWidth` reads a ProseMirror `Node`; this operates on the plain
// `{ colspan, rowspan }[][]` grid. Width is the widest row: each row's own
// colspans plus the colspans of cells from earlier rows whose rowspan still
// overflows into it. Unlike `findWidth`, this does it in a single linear pass
// (a running `carry` of active overflow, expired per row) rather than rescanning
// all prior rows — `fromGrid` is called once per cell during viewer rendering,
// so an O(rows * cells) prepass would be quadratic per render.
function findGridWidth(rows: { colspan: number; rowspan: number }[][]): number {
  const height = rows.length;
  let width = 0;
  // Total colspan of cells from earlier rows still spanning into the current row.
  let carry = 0;
  // expiring[r] = colspan that stops overflowing once we reach row r.
  const expiring = new Array(height + 1).fill(0);
  for (let row = 0; row < height; row++) {
    carry -= expiring[row];
    let rowWidth = carry;
    for (const cell of rows[row]) {
      rowWidth += cell.colspan;
      if (cell.rowspan > 1) {
        carry += cell.colspan;
        const expireAt = row + cell.rowspan; // first row this cell no longer covers
        if (expireAt <= height) {
          expiring[expireAt] += cell.colspan;
        }
      }
    }
    if (rowWidth > width) {
      width = rowWidth;
    }
  }
  return width;
}

function findWidth(table: Node): number {
  let width = -1;
  let hasRowSpan = false;
  for (let row = 0; row < table.childCount; row++) {
    const rowNode = table.child(row);
    let rowWidth = 0;
    if (hasRowSpan) {
      for (let j = 0; j < row; j++) {
        const prevRow = table.child(j);
        for (let i = 0; i < prevRow.childCount; i++) {
          const cell = prevRow.child(i);
          if (j + cell.attrs.rowspan > row) {
            rowWidth += cell.attrs.colspan;
          }
        }
      }
    }
    for (let i = 0; i < rowNode.childCount; i++) {
      const cell = rowNode.child(i);
      rowWidth += cell.attrs.colspan;
      if (cell.attrs.rowspan > 1) {
        hasRowSpan = true;
      }
    }
    if (width == -1) {
      width = rowWidth;
    } else if (width != rowWidth) {
      width = Math.max(width, rowWidth);
    }
  }
  return width;
}

function findBadColWidths(map: TableMap, colWidths: ColWidths, table: Node): void {
  if (!map.problems) {
    map.problems = [];
  }
  const seen: Record<number, boolean> = {};
  for (let i = 0; i < map.map.length; i++) {
    const pos = map.map[i];
    if (seen[pos]) {
      continue;
    }
    seen[pos] = true;
    const node = table.nodeAt(pos);
    if (!node) {
      throw new RangeError(`No cell with offset ${pos} found`);
    }

    let updated = null;
    const attrs = node.attrs as CellAttrs;
    for (let j = 0; j < attrs.colspan; j++) {
      const col = (i + j) % map.width;
      const colWidth = colWidths[col * 2];
      if (!(colWidth === null) && (!attrs.colwidth || attrs.colwidth[j] != colWidth)) {
        (updated || (updated = freshColWidth(attrs)))[j] = colWidth;
      }
    }
    if (updated) {
      map.problems.unshift({
        type: 'colwidth mismatch',
        pos,
        colwidth: updated,
      });
    }
  }
}

function freshColWidth(attrs: Attrs): ColWidths {
  if (attrs.colwidth) {
    return attrs.colwidth.slice();
  }
  const result: ColWidths = [];
  for (let i = 0; i < attrs.colspan; i++) {
    result.push(0);
  }
  return result;
}
