import type {
  IRicosEditor,
  IsVisible,
  PluginToolbarConfig,
  ResolveReferenceElement,
  RicosPluginToolbarNamesValues,
  RicosServices,
  ToolbarButtonRenderers,
} from './../ricos-types/index.js';
import type { NodeSelection, Selection } from './../tiptap/pm/state.js';

import { RicosPluginToolbarButton } from './plugin-toolbar-button.js';

export class RicosPluginToolbar {
  buttons: RicosPluginToolbarButton[];

  pluginType: RicosPluginToolbarNamesValues;

  customIsVisible?: IsVisible;

  customResolveReferenceElement?: ResolveReferenceElement;

  constructor(
    toolbar: PluginToolbarConfig,
    pluginType: RicosPluginToolbarNamesValues,
    services: RicosServices,
    config: Record<string, any>
  ) {
    this.buttons =
      toolbar
        ?.getButtons(config, services)
        ?.map(button => RicosPluginToolbarButton.of(button, services)) || [];
    this.pluginType = pluginType;
    this.customIsVisible = toolbar.isVisible;
    this.customResolveReferenceElement = toolbar.resolveReferenceElement;
  }

  static of(
    toolbar: PluginToolbarConfig,
    pluginType: RicosPluginToolbarNamesValues,
    services: RicosServices,
    config: Record<string, any>
  ) {
    return new RicosPluginToolbar(toolbar, pluginType, services, config);
  }

  getButtons() {
    return this.buttons;
  }

  toToolbarItemsConfig() {
    return this.buttons.map(button => button.toToolbarItemConfig());
  }

  getToolbarButtonsRenderers() {
    return this.buttons.reduce((renderers, button) => {
      return {
        ...renderers,
        ...button.getRenderer(),
      };
    }, {} as ToolbarButtonRenderers);
  }

  isVisible(selection: Selection | NodeSelection, editor: IRicosEditor): boolean {
    if (!this.buttons.length) {
      return false;
    }
    const isVisibleInSelection =
      'node' in selection && selection.node?.type.name === this.pluginType;

    return this.customIsVisible
      ? isVisibleInSelection || this.customIsVisible(selection as Selection, editor)
      : isVisibleInSelection;
  }

  getReferenceElementResolver() {
    return this.customResolveReferenceElement;
  }
}
