import { TIPTAP_CARD_TYPE } from './../../../ricos-content/index.js';

import type { QueryItemCreator } from '../../types.js';

const NAME = 'isNodeSelected';
const isNodeSelectedFn: QueryItemCreator =
  ({ editorQuery }) =>
  (nodeId: string) => {
    if (editorQuery.query.isMultipleSelection()) {
      return false;
    }
    const selectedTreeNode = editorQuery.selection().doc?.children?.[0];
    const targetNode =
      selectedTreeNode?.type() === TIPTAP_CARD_TYPE
        ? selectedTreeNode.children?.[0]
        : selectedTreeNode;
    return targetNode?.toNode?.()?.id === nodeId;
  };

export const isNodeSelected = { NAME, query: isNodeSelectedFn };
