import type { PmConverters } from './../../pm-converters/collect.js';
import type { RicosStyles } from './../../ricos-styles/index.js';
import type { Editor } from './../../tiptap/core/index.js';

import type { QueryItem, QueryItemCreator } from '../types.js';
import { Selection } from './selection.js';
import { EditorStateQuery } from './state.js';
import { StylesQuery } from './style-query.js';

export class EditorQuery {
  private _selection: Selection;

  private _styles: StylesQuery;

  private _state: EditorStateQuery;

  // oxlint-disable-next-line no-useless-constructor
  constructor(
    private editor: Editor,
    private ricosStyles: RicosStyles,
    private converters: PmConverters
  ) {
    this._selection = new Selection(this.editor, this.converters);
    this._state = new EditorStateQuery(this.editor, this.converters);

    // add when styles theme or  doc change event
    this._styles = new StylesQuery(this.ricosStyles);

    this.editor.on('transaction', () => {
      this._selection = new Selection(this.editor, this.converters);
    });
  }

  selection(): Selection {
    return this._selection;
  }

  state(): EditorStateQuery {
    return this._state;
  }

  styles(): StylesQuery {
    return this._styles;
  }

  query: Record<string, QueryItem> = {};

  addQuery = (name: string, query: QueryItemCreator) => {
    if (this.query[name]) {
      throw `Query ${name} already exists`;
    }
    this.query[name] = query({ editorQuery: this });
  };
}
