import type { TopicDescriptor } from './../ricos-types/index.js';

import type { RicosEventData } from './event-data.js';
import type { EventSubscriber } from './ricos-event.js';

export type SubscriberSyncProcessing = {
  subscriberId: EventSubscriber['id'];
  duration: number;
};

type PublishingMetadata = {
  topic: TopicDescriptor;
  eventId: number;
  data: RicosEventData;
  duration: number;
  timestamp: Date;
};

export type AsyncPublishingMetadata = PublishingMetadata & {
  isAsync: true;
};

export type SyncPublishingMetadata = PublishingMetadata & {
  isAsync: false;
  processings: SubscriberSyncProcessing[];
};

export interface EventLogger {
  log: (metadata: AsyncPublishingMetadata | SyncPublishingMetadata | string) => void;
}

export const getEventLogger = (isDebugMode: boolean): EventLogger => {
  if (typeof window === 'undefined') {
    return { log: () => {} };
  }
  if (/eventLogger=console/i.test(window.location.search) || isDebugMode) {
    return {
      log: (metadata: SyncPublishingMetadata | AsyncPublishingMetadata | string) =>
        // oxlint-disable-next-line no-console
        console.debug(metadata),
    };
  }
  return { log: () => {} };
};
