import { PmNodeType } from './../../../_shared/pm-node-types.js';

import type { IEditorQuery, ITreeNodeQuery, QueryItem } from '../../types.js';

const NAME = 'isListItem';
const isListItemFn: QueryItem =
  ({ editorQuery }: { editorQuery: IEditorQuery }) =>
  () => {
    const { doc } = editorQuery.selection();
    let hasDescendantListItem = false;

    doc.descendants((node: ITreeNodeQuery) => {
      if (node.type() === PmNodeType.LIST_ITEM) {
        hasDescendantListItem = true;
        return false;
      }
      return true;
    });

    return hasDescendantListItem;
  };

export const isListItem = { NAME, query: isListItemFn };
